import type { Tool } from "./types";

export type FaqItem = {
  q: Record<"en" | "fr", string>;
  a: Record<"en" | "fr", string>;
};

function universal(name: Record<"en" | "fr", string>, isNetwork: boolean): FaqItem[] {
  return [
    {
      q: { en: `Is ${name.en} free to use?`, fr: `${name.fr} est-il gratuit ?` },
      a: {
        en: "Yes, completely free — no account, no signup, no hidden fees.",
        fr: "Oui, entièrement gratuit — sans compte, sans inscription, sans frais cachés.",
      },
    },
    {
      q: {
        en: isNetwork ? "Is my data stored on your servers?" : "Are my files uploaded to a server?",
        fr: isNetwork ? "Mes données sont-elles stockées sur vos serveurs ?" : "Mes fichiers sont-ils téléchargés sur un serveur ?",
      },
      a: {
        en: isNetwork
          ? "A request passes through our proxy to fetch external data. Nothing you enter is stored in a database. Standard server access logs (IP address, timestamp) are retained for ~30 days for security purposes — see our privacy policy."
          : "No. All processing happens locally in your browser. Your files never leave your device.",
        fr: isNetwork
          ? "Une requête transite par notre proxy pour récupérer des données externes. Vos saisies ne sont pas stockées en base de données. Les logs d'accès HTTP standard (adresse IP, horodatage) sont conservés environ 30 jours à des fins de sécurité — voir notre politique de confidentialité."
          : "Non. Tout le traitement s'effectue localement dans votre navigateur. Vos fichiers ne quittent jamais votre appareil.",
      },
    },
    {
      q: {
        en: `Does ${name.en} work offline?`,
        fr: `${name.fr} fonctionne-t-il hors ligne ?`,
      },
      a: {
        en: isNetwork
          ? "No — an internet connection is required to fetch external data."
          : "Yes — once the page has loaded, the tool works entirely offline.",
        fr: isNetwork
          ? "Non — une connexion internet est requise pour récupérer les données externes."
          : "Oui — une fois la page chargée, l'outil fonctionne entièrement hors ligne.",
      },
    },
  ];
}

const SPECIFIC: Partial<Record<string, FaqItem[]>> = {
  "json-formatter": [
    { q: { en: "Why does my JSON fail when JavaScript accepts it?", fr: "Pourquoi mon JSON échoue-t-il alors que JavaScript l'accepte ?" }, a: { en: "Because a JavaScript object literal allows things JSON doesn't: trailing commas, single quotes, unquoted keys, comments, undefined. The error message names which one it found and where. Replace it with the JSON form, usually double quotes or removing the extra comma.", fr: "Parce qu'un objet littéral JavaScript accepte ce que le JSON refuse : virgules finales, apostrophes, clés sans guillemets, commentaires, undefined. Le message d'erreur nomme celui qu'il a trouvé et où. Remplacez-le par la forme JSON, en général des guillemets doubles ou la suppression de la virgule en trop." } },
    { q: { en: "Why do long IDs change in other formatters?", fr: "Pourquoi les longs identifiants changent-ils dans d'autres formateurs ?" }, a: { en: "Because JSON.parse stores numbers as 64-bit floats, exact only up to 9,007,199,254,740,991. Larger integers are rounded as soon as they're read. This formatter keeps their original digits, but your own code will still round them unless the API sends them as strings.", fr: "Parce que JSON.parse stocke les nombres en flottants 64 bits, exacts seulement jusqu'à 9 007 199 254 740 991. Les entiers plus grands sont arrondis dès la lecture. Ce formateur garde leurs chiffres d'origine, mais votre propre code les arrondira toujours, sauf si l'API les envoie en chaînes." } },
    { q: { en: "Can I format a tsconfig.json that contains comments?", fr: "Puis-je formater un tsconfig.json qui contient des commentaires ?" }, a: { en: "Not as is. The formatter follows strict JSON and reports the comment as an error. tsconfig.json accepts comments, so that's not a problem in the file itself; remove them only in a copy if you need strict JSON.", fr: "Pas tel quel. Le formateur suit le JSON strict et signale le commentaire comme une erreur. tsconfig.json accepte les commentaires, ce n'est donc pas un problème dans le fichier lui-même ; retirez-les seulement dans une copie si vous avez besoin de JSON strict." } },
    { q: { en: "Does sorting keys change the order of arrays?", fr: "Le tri des clés change-t-il l'ordre des tableaux ?" }, a: { en: "No. Only the keys inside objects are sorted, at every level. Arrays keep their original order, because the position of an item in an array is part of the data.", fr: "Non. Seules les clés à l'intérieur des objets sont triées, à tous les niveaux. Les tableaux gardent leur ordre d'origine, car la position d'un élément dans un tableau fait partie de la donnée." } },
    { q: { en: "Is my JSON sent to a server?", fr: "Mon JSON est-il envoyé à un serveur ?" }, a: { en: "No. Parsing and formatting run in your browser, and nothing is stored. You can paste responses that contain tokens or personal data, though as a habit it's still wise to remove secrets before sharing a formatted payload with anyone.", fr: "Non. L'analyse et la mise en forme se font dans votre navigateur, et rien n'est conservé. Vous pouvez coller des réponses qui contiennent des jetons ou des données personnelles ; par principe, retirez tout de même les secrets avant de partager un payload formaté avec quelqu'un." } },
  ],
  "image-converter": [
    { q: { en: "Why did my file get bigger after converting it?", fr: "Pourquoi mon fichier est-il plus lourd après conversion ?" }, a: { en: "Most often because a photo was exported as PNG, which is lossless and can't compress photographic detail the way JPG or WebP do. It also happens when a small, already compressed JPG is re-encoded at quality 100. Pick WebP or JPG at 80, and reduce the width if the image is larger than where it will be displayed.", fr: "Le plus souvent parce qu'une photo a été exportée en PNG, format sans perte qui ne compresse pas le détail photographique comme le JPG ou le WebP. Cela arrive aussi quand un petit JPG déjà compressé est réencodé en qualité 100. Choisissez WebP ou JPG en 80, et réduisez la largeur si l'image est plus grande que sa zone d'affichage." } },
    { q: { en: "Can I convert an image to AVIF?", fr: "Puis-je convertir une image en AVIF ?" }, a: { en: "Not with this tool. Browsers decode AVIF but don't give web pages an AVIF encoder, so AVIF is accepted as input only. For the web, WebP gives most of the gain and is supported everywhere.", fr: "Pas avec cet outil. Les navigateurs décodent l'AVIF mais ne donnent pas d'encodeur AVIF aux pages web : l'AVIF n'est donc accepté qu'en entrée. Pour le web, le WebP apporte l'essentiel du gain et fonctionne partout." } },
    { q: { en: "Does converting remove the photo's location data?", fr: "La conversion retire-t-elle la localisation de la photo ?" }, a: { en: "Yes. The image is re-encoded from its pixels, so EXIF metadata such as GPS coordinates, camera model and date is not carried over to the new file. Keep the original if you need that information.", fr: "Oui. L'image est réencodée à partir de ses pixels : les métadonnées EXIF, comme les coordonnées GPS, le modèle d'appareil et la date, ne passent pas dans le nouveau fichier. Gardez l'original si vous avez besoin de ces informations." } },
    { q: { en: "Why won't my iPhone photo (HEIC) open?", fr: "Pourquoi ma photo d'iPhone (HEIC) ne s'ouvre-t-elle pas ?" }, a: { en: "Because the conversion relies on your browser to decode the image, and only Safari reads HEIC. Export the photo as JPG from the iPhone or from Preview on a Mac, or set the iPhone camera to Most Compatible so it saves JPG from then on.", fr: "Parce que la conversion s'appuie sur votre navigateur pour décoder l'image, et que seul Safari lit le HEIC. Exportez la photo en JPG depuis l'iPhone ou depuis Aperçu sur Mac, ou réglez l'appareil photo de l'iPhone sur « Le plus compatible » pour qu'il enregistre en JPG." } },
    { q: { en: "Which width should I pick for a website?", fr: "Quelle largeur choisir pour un site web ?" }, a: { en: "About twice the width at which the image is displayed, to stay sharp on high-density screens: 1280 pixels for an image shown around 640 pixels wide, 1920 for a full-width banner. Going larger mostly adds weight.", fr: "Environ deux fois la largeur d'affichage de l'image, pour rester net sur les écrans haute densité : 1280 pixels pour une image affichée sur environ 640 pixels, 1920 pour un bandeau pleine largeur. Au-delà, on ajoute surtout du poids." } },
  ],
  "pdf-converter": [
    { q: { en: "Can this tool convert a PDF to an editable Word document?", fr: "Cet outil peut-il convertir un PDF en document Word modifiable ?" }, a: { en: "No. It converts PDF pages to PNG or JPEG images, or assembles images into a PDF. Getting editable text needs a PDF-to-Word converter that extracts the text, or OCR for scanned pages.", fr: "Non. Il convertit les pages d'un PDF en images PNG ou JPEG, ou assemble des images en PDF. Obtenir un texte modifiable demande un convertisseur PDF vers Word qui extrait le texte, ou de l'OCR pour des pages scannées." } },
    { q: { en: "Which scale should I choose for PDF to images?", fr: "Quelle échelle choisir pour convertir un PDF en images ?" }, a: { en: "2× for screens, slides and websites, which gives about 1190 pixels wide for an A4 page. 3× for printing or for plans you need to zoom into. 1× is only for small previews.", fr: "2× pour les écrans, les diapositives et les sites, soit environ 1190 pixels de large pour une page A4. 3× pour imprimer ou pour des plans dans lesquels il faut zoomer. 1× ne sert qu'aux petits aperçus." } },
    { q: { en: "Why is the page of my PDF so large when I open it?", fr: "Pourquoi la page de mon PDF est-elle si grande à l'ouverture ?" }, a: { en: "Because each page takes the pixel size of its image, one pixel per point. A full-resolution phone photo makes a page over a metre wide. Reduce the photos to about 1600 pixels wide before converting, and the pages and the file become much smaller.", fr: "Parce que chaque page prend la taille en pixels de son image, un pixel par point. Une photo de téléphone en pleine résolution donne une page de plus d'un mètre de large. Réduisez les photos à environ 1600 pixels de large avant la conversion : les pages et le fichier deviennent bien plus petits." } },
    { q: { en: "What image formats can I turn into a PDF?", fr: "Quels formats d'image puis-je transformer en PDF ?" }, a: { en: "JPG and PNG directly. Other formats your browser can open, such as WebP or AVIF, are converted to PNG first, then added. Each image becomes one page, in the order you added them.", fr: "Le JPG et le PNG directement. Les autres formats que votre navigateur sait ouvrir, comme le WebP ou l'AVIF, sont d'abord convertis en PNG, puis ajoutés. Chaque image devient une page, dans l'ordre d'ajout." } },
    { q: { en: "Why won't my PDF open?", fr: "Pourquoi mon PDF ne s'ouvre-t-il pas ?" }, a: { en: "Most often because it's protected by a password, which the tool can't remove. Open it in your PDF reader with the password and save a copy without protection if you're allowed to, then convert that copy.", fr: "Le plus souvent parce qu'il est protégé par un mot de passe, que l'outil ne peut pas retirer. Ouvrez-le dans votre lecteur PDF avec le mot de passe et enregistrez une copie sans protection si vous en avez le droit, puis convertissez cette copie." } },
  ],
  "audio-converter": [{ q: { en: "Why does the first conversion take longer?", fr: "Pourquoi la première conversion prend-elle plus de temps ?" }, a: { en: "The FFmpeg WebAssembly engine (~20 MB) needs to load once. Subsequent conversions are instant.", fr: "Le moteur FFmpeg WebAssembly (~20 Mo) doit se charger une fois. Les conversions suivantes sont instantanées." } },
    { q: { en: "Does converting MP3 to a higher bitrate improve the quality?", fr: "Convertir un MP3 vers un débit supérieur améliore-t-il la qualité ?" }, a: { en: "No. Lossy formats discard detail permanently, so re-encoding at 320 kbps from a 128 kbps source produces a larger file carrying the same lost information — plus whatever the second encode discards on top. Always convert from the lossless original when you have it.", fr: "Non. Les formats avec perte écartent définitivement du détail : ré-encoder à 320 kbps depuis une source à 128 kbps produit un fichier plus lourd portant la même information perdue — augmentée de ce que le second encodage écarte à son tour. Partez toujours de l'original sans perte quand vous en disposez." } },
    { q: { en: "Which bitrate should I choose?", fr: "Quel débit choisir ?" }, a: { en: "For music, 192 kbps is where most listeners stop hearing a difference on ordinary equipment, and 256 or 320 kbps buys archival headroom. Speech is far more forgiving — a podcast stays perfectly clear at 64 to 96 kbps. The setting applies to lossy formats only: WAV ignores it and FLAC sizes itself from the content.", fr: "Pour de la musique, 192 kbps est le point où la plupart des auditeurs cessent d'entendre une différence sur un équipement ordinaire, et 256 ou 320 kbps offrent une marge d'archivage. La parole est bien plus tolérante — un podcast reste parfaitement clair entre 64 et 96 kbps. Le réglage ne concerne que les formats avec perte : le WAV l'ignore et le FLAC se dimensionne d'après le contenu." } },
  ],
  "video-converter": [{ q: { en: "Can I extract the audio track from a video?", fr: "Puis-je extraire la piste audio d'une vidéo ?" }, a: { en: "Not with this tool — the output formats are all video containers plus GIF, so there is no audio-only target. Converting to an audio file is a different operation; the Audio Converter handles that side, though it expects an audio file as its input rather than a video.", fr: "Pas avec cet outil — les formats de sortie sont tous des conteneurs vidéo, plus le GIF : aucune cible purement audio n'est proposée. Convertir vers un fichier audio est une autre opération ; le convertisseur audio couvre ce versant, mais il attend un fichier audio en entrée plutôt qu'une vidéo." } },
    { q: { en: "Why is my GIF so much heavier than the video?", fr: "Pourquoi mon GIF est-il bien plus lourd que la vidéo ?" }, a: { en: "Because GIF compresses far worse than any video codec and is limited to 256 colours per frame. A three-second clip weighing 200 kB as MP4 routinely exceeds several megabytes as GIF, with visible banding on gradients. GIF is worth it only for very short clips that must play where video is not accepted.", fr: "Parce que le GIF compresse bien plus mal que n'importe quel codec vidéo et se limite à 256 couleurs par image. Un clip de trois secondes pesant 200 ko en MP4 dépasse couramment plusieurs mégaoctets en GIF, avec des bandes visibles sur les dégradés. Le GIF ne vaut le coup que pour de très courts clips devant être lus là où la vidéo n'est pas acceptée." } },
    { q: { en: "Why is conversion so slow compared with a desktop application?", fr: "Pourquoi la conversion est-elle si lente face à une application de bureau ?" }, a: { en: "Because FFmpeg runs here as WebAssembly on the CPU, without the hardware acceleration a native application uses. Memory is the harder limit: the file is held in RAM rather than streamed from disk, so a large source can exhaust the tab. Lowering the output resolution helps with both; files of several hundred megabytes are better handled by a desktop tool.", fr: "Parce que FFmpeg s'exécute ici en WebAssembly sur le processeur, sans l'accélération matérielle qu'utilise une application native. La mémoire est la limite la plus dure : le fichier est gardé en RAM plutôt que lu en flux depuis le disque, si bien qu'une source volumineuse peut épuiser l'onglet. Réduire la résolution de sortie aide sur les deux plans ; les fichiers de plusieurs centaines de mégaoctets se traitent mieux avec un outil de bureau." } },
  ],
  "pdf-merge": [
    { q: { en: "Will my signed contract still be valid after merging?", fr: "Mon contrat signé restera-t-il valide après la fusion ?" }, a: { en: "Its electronic signature won't be. The signature is tied to the original file's exact content, and merging creates a new file. The signature image stays visible on the page, but a PDF reader will no longer confirm it. Send signed documents as separate attachments.", fr: "Sa signature électronique, non. La signature est liée au contenu exact du fichier d'origine, et la fusion crée un nouveau fichier. L'image de la signature reste visible sur la page, mais un lecteur PDF ne pourra plus la confirmer. Envoyez les documents signés en pièces jointes séparées." } },
    { q: { en: "Does merging reduce the quality of my PDFs?", fr: "La fusion réduit-elle la qualité de mes PDF ?" }, a: { en: "No. Pages are copied without being redrawn or recompressed, so text stays selectable and images keep their original quality. It also means the merged file isn't smaller than the sum of its parts.", fr: "Non. Les pages sont copiées sans être redessinées ni recompressées : le texte reste sélectionnable et les images gardent leur qualité d'origine. Cela veut aussi dire que le fichier fusionné n'est pas plus léger que la somme de ses parties." } },
    { q: { en: "Why won't one of my PDFs merge?", fr: "Pourquoi l'un de mes PDF refuse-t-il la fusion ?" }, a: { en: "It's either protected by a password or damaged. The error message gives its name. Remove it to merge the others, or open it in your PDF reader with the password and save a copy without protection if you're allowed to.", fr: "Il est soit protégé par mot de passe, soit endommagé. Le message d'erreur donne son nom. Retirez-le pour fusionner les autres, ou ouvrez-le dans votre lecteur PDF avec le mot de passe et enregistrez une copie sans protection si vous en avez le droit." } },
    { q: { en: "Can I add JPG or PNG scans?", fr: "Puis-je ajouter des scans en JPG ou en PNG ?" }, a: { en: "Not directly: the tool only takes PDFs. Convert the images first with the JPG to PDF or PNG to PDF converter, which puts one image per page, then merge the result with your other documents.", fr: "Pas directement : l'outil n'accepte que des PDF. Convertissez d'abord les images avec le convertisseur JPG vers PDF ou PNG vers PDF, qui place une image par page, puis fusionnez le résultat avec vos autres documents." } },
    { q: { en: "Is there a limit on the number of files?", fr: "Y a-t-il une limite au nombre de fichiers ?" }, a: { en: "No fixed limit. The work happens in your browser's memory, so the practical limit depends on your device and on the total size: a few dozen ordinary documents merge quickly, while hundreds of megabytes of scans can make the tab slow.", fr: "Pas de limite fixe. Le travail se fait dans la mémoire du navigateur : la limite pratique dépend de votre appareil et du poids total. Quelques dizaines de documents ordinaires fusionnent vite, alors que des centaines de mégaoctets de scans peuvent ralentir l'onglet." } },
  ],
  "qr-generator": [
    { q: { en: "Do QR codes made here expire?", fr: "Les QR codes créés ici expirent-ils ?" }, a: { en: "No. The content is written inside the code, with no redirect through our site, so there's nothing to expire or switch off. The code works as long as the address it contains works.", fr: "Non. Le contenu est écrit dans le code, sans redirection par notre site : il n'y a rien qui puisse expirer ou être désactivé. Le code fonctionne tant que l'adresse qu'il contient fonctionne." } },
    { q: { en: "What size should a printed QR code be?", fr: "Quelle taille donner à un QR code imprimé ?" }, a: { en: "Roughly one tenth of the distance it will be scanned from, and not much under 2 cm. Use the SVG file so it stays sharp at any size, keep the white margin around it, and test the printed proof with two phones.", fr: "Environ un dixième de la distance à laquelle il sera scanné, et pas beaucoup moins de 2 cm. Utilisez le fichier SVG pour qu'il reste net à toutes les tailles, gardez la marge blanche autour, et testez l'épreuve imprimée avec deux téléphones." } },
    { q: { en: "Why doesn't my Wi-Fi QR code connect?", fr: "Pourquoi mon QR code Wi-Fi ne connecte-t-il pas ?" }, a: { en: "Most often because the password contains a special character, such as ; or :, that wasn't escaped, so the phone reads a truncated password. The Wi-Fi mode here escapes them for you. Also check the security type (WPA for almost every current router) and whether the network is hidden.", fr: "Le plus souvent parce que le mot de passe contient un caractère spécial, comme ; ou :, qui n'a pas été échappé : le téléphone lit alors un mot de passe tronqué. Le mode Wi-Fi d'ici les échappe pour vous. Vérifiez aussi le type de sécurité (WPA pour presque toutes les box actuelles) et si le réseau est masqué." } },
    { q: { en: "Which error-correction level should I choose?", fr: "Quel niveau de correction d'erreur choisir ?" }, a: { en: "M works for most uses. Choose Q or H if the code will be printed on something that gets scratched, folded or partly covered, and L if the content is long and the code must stay small. Higher levels make the code denser.", fr: "M convient à la plupart des usages. Choisissez Q ou H si le code sera imprimé sur un support qui se raye, se plie ou peut être en partie masqué, et L si le contenu est long et que le code doit rester petit. Les niveaux élevés rendent le code plus dense." } },
    { q: { en: "SVG or PNG?", fr: "SVG ou PNG ?" }, a: { en: "SVG for anything printed or resized, since it's a vector file that stays sharp at any size. PNG for screens, slides, emails and documents that expect an image, at 256 or 512 pixels.", fr: "SVG pour tout ce qui est imprimé ou redimensionné, puisque c'est un fichier vectoriel qui reste net à toutes les tailles. PNG pour les écrans, les diapositives, les e-mails et les documents qui attendent une image, en 256 ou 512 pixels." } },
  ],
  "base64": [{ q: { en: "Can I encode a file, not just text?", fr: "Puis-je encoder un fichier, pas seulement du texte ?" }, a: { en: "Not here — this tool works on text you paste in, in both directions. To turn a file into a data URI you need a converter that reads the file as bytes; pasting a file's contents into the text field will encode whatever your editor showed you, which is not the same thing for anything but plain text.", fr: "Pas ici — cet outil travaille sur du texte collé, dans les deux sens. Pour transformer un fichier en data URI, il faut un convertisseur qui lise le fichier comme des octets ; coller le contenu d'un fichier dans le champ texte encodera ce que votre éditeur vous a affiché, ce qui n'est pas la même chose sauf pour du texte brut." } },
    { q: { en: "Does Base64 protect or hide my data?", fr: "Le Base64 protège-t-il ou masque-t-il mes données ?" }, a: { en: "No. It is a reversible transformation with no key, decodable by anyone in a second — including on this page. A password or an API key placed in a Base64 string is exactly as exposed as if it were written in plain text. Base64 solves transport, not confidentiality.", fr: "Non. C'est une transformation réversible sans clé, que n'importe qui décode en une seconde — y compris sur cette page. Un mot de passe ou une clé d'API placés dans une chaîne Base64 sont exactement aussi exposés que s'ils étaient écrits en clair. Le Base64 règle un problème de transport, pas de confidentialité." } },
    { q: { en: "Why does my string end with one or two equals signs?", fr: "Pourquoi ma chaîne se termine-t-elle par un ou deux signes égal ?" }, a: { en: "Base64 processes the input three bytes at a time and emits four characters for each group. When the length is not a multiple of three, the final group is short and gets padded with equals signs so the output length stays a multiple of four. One sign means one byte was missing, two signs mean two were.", fr: "Le Base64 traite l'entrée par groupes de trois octets et émet quatre caractères par groupe. Quand la longueur n'est pas un multiple de trois, le dernier groupe est incomplet et se voit complété par des signes égal pour que la sortie reste un multiple de quatre. Un signe signifie qu'il manquait un octet, deux signes qu'il en manquait deux." } },
    { q: { en: "Why does a JWT segment fail to decode here?", fr: "Pourquoi un segment de JWT échoue-t-il à se décoder ici ?" }, a: { en: "Because JWTs use the URL-safe alphabet, which replaces plus with minus and slash with underscore, and usually drops the padding. This tool reads standard Base64 only. Swap minus back to plus and underscore back to slash first, and the segment will decode normally.", fr: "Parce que les JWT utilisent l'alphabet URL-safe, qui remplace le plus par un moins et la barre oblique par un tiret bas, en supprimant généralement le remplissage. Cet outil ne lit que le Base64 standard. Remplacez d'abord les moins par des plus et les tirets bas par des barres obliques, et le segment se décodera normalement." } },
  ],
  "markdown-html": [{ q: { en: "Which Markdown flavour is supported?", fr: "Quelle variante de Markdown est supportée ?" }, a: { en: "CommonMark and GitHub Flavored Markdown (GFM) — including tables, task lists and strikethrough.", fr: "CommonMark et GitHub Flavored Markdown (GFM) — y compris les tableaux, les listes de tâches et le texte barré." } },
    { q: { en: "Is the generated HTML safe to put straight on a page?", fr: "Le HTML généré peut-il être publié tel quel ?" }, a: { en: "Only if you wrote the Markdown yourself. Markdown deliberately allows inline HTML and it is not filtered on the way out, so converting text submitted by someone else and injecting the result into a page is a direct route to a cross-site scripting hole. Sanitize the output first in that case.", fr: "Seulement si vous avez écrit le Markdown vous-même. Markdown autorise délibérément le HTML en ligne et celui-ci n'est pas filtré en sortie : convertir un texte soumis par un tiers et injecter le résultat dans une page mène tout droit à une faille de cross-site scripting. Assainissez la sortie au préalable dans ce cas." } },
    { q: { en: "Why did my single line break disappear?", fr: "Pourquoi mon simple saut de ligne a-t-il disparu ?" }, a: { en: "Because a single newline inside a paragraph does not produce a break — Markdown joins those lines so you can wrap your source freely. End the line with two spaces, or a backslash, to force one. The two-space form is invisible in editors and often stripped by trailing-whitespace tooling, which is why breaks vanish between writing and publishing.", fr: "Parce qu'un simple retour à la ligne dans un paragraphe ne produit pas de saut — Markdown fusionne ces lignes pour vous laisser replier votre source librement. Terminez la ligne par deux espaces, ou par un antislash, pour en forcer un. La forme à deux espaces est invisible dans les éditeurs et souvent supprimée par les outils de nettoyage d'espaces, d'où des sauts qui s'évaporent entre l'écriture et la publication." } },
  ],
  "hash-generator": [{ q: { en: "Can I hash a file, not just text?", fr: "Puis-je hasher un fichier, pas seulement du texte ?" }, a: { en: "Yes — drag and drop any file to compute its MD5, SHA-1 and SHA-256 fingerprints simultaneously.", fr: "Oui — glissez-déposez n'importe quel fichier pour calculer simultanément ses empreintes MD5, SHA-1 et SHA-256." } },
    { q: { en: "Can I recover the original text from a hash?", fr: "Puis-je retrouver le texte d'origine à partir d'une empreinte ?" }, a: { en: "Not by reversing it — the function only goes one way. But short or common inputs are trivially recovered by looking the digest up in a precomputed table, which is why hashing a password without a random salt offers so little protection. A hash conceals nothing whose value was already guessable.", fr: "Pas en l'inversant — la fonction ne va que dans un sens. Mais les entrées courtes ou courantes se retrouvent trivialement en cherchant le condensat dans une table précalculée, ce qui explique qu'une empreinte de mot de passe sans sel aléatoire protège si peu. Une empreinte ne dissimule rien dont la valeur était déjà devinable." } },
    { q: { en: "Are MD5 and SHA-1 still safe to use?", fr: "MD5 et SHA-1 sont-ils encore sûrs ?" }, a: { en: "Not against anyone trying to fool you. Both are broken in the sense that two different files sharing a digest can be constructed in practice, so neither should back a signature or a security check. They remain useful where no adversary exists — matching a legacy vendor checksum, deduplicating files, keying a cache.", fr: "Pas face à quelqu'un qui cherche à vous tromper. Les deux sont cassés au sens où l'on sait construire en pratique deux fichiers différents partageant un même condensat : aucun ne doit donc fonder une signature ou un contrôle de sécurité. Ils restent utiles là où aucun adversaire n'existe — correspondre au checksum d'un éditeur ancien, dédupliquer des fichiers, indexer un cache." } },
    { q: { en: "Why does the same text give a different hash elsewhere?", fr: "Pourquoi le même texte donne-t-il une empreinte différente ailleurs ?" }, a: { en: "Almost always because the bytes differ even though the text looks identical. A trailing newline, Windows CRLF line endings instead of a bare LF, a byte-order mark, or a paste that turned straight quotes into typographic ones each change the input completely. Hashing the file itself rather than its pasted contents removes the ambiguity.", fr: "Presque toujours parce que les octets diffèrent alors que le texte paraît identique. Un saut de ligne final, des fins de ligne CRLF Windows au lieu d'un simple LF, une marque d'ordre des octets, ou un collage ayant transformé les guillemets droits en guillemets typographiques modifient chacun entièrement l'entrée. Calculer l'empreinte du fichier lui-même plutôt que de son contenu collé lève l'ambiguïté." } },
  ],
  "regex-tester": [{ q: { en: "Which regex flags can I toggle?", fr: "Quels flags regex puis-je activer ?" }, a: { en: "Three: i (case-insensitive), m (multiline) and s (dotAll). The global flag g is always on, because the tester exists to show every match rather than just the first. There is no toggle for the unicode flag u. Capture groups work, including named ones, but the results panel lists them by position rather than by name.", fr: "Trois : i (insensible à la casse), m (multilignes) et s (dotAll). Le flag global g est toujours actif, puisque le testeur existe pour montrer toutes les correspondances et non la première. Il n'y a pas d'interrupteur pour le flag unicode u. Les groupes de capture fonctionnent, y compris nommés, mais le panneau de résultats les liste par position plutôt que par nom." } },
    { q: { en: "Why does my pattern match here but fail in my code?", fr: "Pourquoi mon motif correspond-il ici mais échoue-t-il dans mon code ?" }, a: { en: "Two usual causes. The global flag is always on in this tester, so a pattern you copy without it will only return the first match. And a global regex kept in a variable holds an internal position between calls, so reusing it in a loop skips matches — reset lastIndex, or use matchAll.", fr: "Deux causes habituelles. Le flag global est toujours actif dans ce testeur : un motif recopié sans lui ne renverra que la première correspondance. Et une regex globale conservée dans une variable garde une position interne entre les appels, si bien que la réutiliser dans une boucle saute des correspondances — réinitialisez lastIndex, ou passez par matchAll." } },
    { q: { en: "The page freezes on a long text — what happened?", fr: "La page se fige sur un texte long — que s'est-il passé ?" }, a: { en: "You have most likely hit catastrophic backtracking. Patterns with nested quantifiers — a repeatable group inside something else repeatable — can take exponential time on input that does not match. It is invisible on a short sample and hangs the tab on a longer one. Such a pattern is not safe to run against user input; make the inner quantifier more specific or anchor the expression.", fr: "Vous avez probablement déclenché un retour arrière catastrophique. Les motifs à quantificateurs imbriqués — un groupe répétable dans quelque chose de répétable — peuvent demander un temps exponentiel sur une entrée qui ne correspond pas. C'est invisible sur un court échantillon et fige l'onglet sur un plus long. Un tel motif n'est pas déployable sur des saisies utilisateur : rendez le quantificateur interne plus spécifique ou ancrez l'expression." } },
    { q: { en: "Why does my pattern stop at the end of a line?", fr: "Pourquoi mon motif s'arrête-t-il en fin de ligne ?" }, a: { en: "Because the dot does not match a newline unless the s flag is on. Enable it to let an expression span several lines. The separate m flag changes something else: it makes the start and end anchors match at every line break instead of only at the boundaries of the whole text.", fr: "Parce que le point ne correspond pas à un saut de ligne tant que le flag s n'est pas actif. Activez-le pour qu'une expression puisse s'étendre sur plusieurs lignes. Le flag m, distinct, fait autre chose : il fait correspondre les ancres de début et de fin à chaque saut de ligne au lieu des seules bornes du texte entier." } },
  ],
  "ip-lookup": [{ q: { en: "Why might the location be inaccurate?", fr: "Pourquoi la localisation peut-elle être imprécise ?" }, a: { en: "GeoIP databases have a natural margin of error, especially for mobile networks and VPN exit nodes.", fr: "Les bases de données GeoIP ont une marge d'erreur naturelle, notamment pour les réseaux mobiles et les nœuds de sortie VPN." } }],
  "uuid-generator": [{ q: { en: "Which UUID version does this tool generate?", fr: "Quelle version d'UUID cet outil génère-t-il ?" }, a: { en: "Version 4 only — the fully random variant, and the right default in almost every case. For reference, v1 embeds a timestamp and a MAC address, and v7 is time-ordered random, which makes it sortable and friendlier to clustered database indexes. If you specifically need v1 or v7, use a library in your own stack.", fr: "La version 4 uniquement — la variante entièrement aléatoire, et le bon défaut dans la quasi-totalité des cas. Pour mémoire, la v1 intègre un horodatage et une adresse MAC, et la v7 est aléatoire mais ordonnée dans le temps, donc triable et plus tendre pour les index clusterisés. Si vous avez spécifiquement besoin de v1 ou v7, passez par une bibliothèque dans votre propre stack." } },
    { q: { en: "What are the odds of generating the same UUID twice?", fr: "Quelles sont les chances de générer deux fois le même UUID ?" }, a: { en: "Negligible. A version 4 UUID carries 122 random bits, so generating a billion per second for a century still leaves the probability of one duplicate far below the odds of your storage silently corrupting a row. Real-world collisions trace back to a weak random source, not to the format running out of space.", fr: "Négligeables. Un UUID version 4 porte 122 bits aléatoires : en générer un milliard par seconde pendant un siècle laisse encore la probabilité d'un doublon très en dessous du risque que votre stockage corrompe silencieusement une ligne. Les collisions constatées en production viennent d'une source aléatoire faible, pas d'un format à court de place." } },
    { q: { en: "Are these UUIDs safe to use as secret tokens?", fr: "Ces UUID peuvent-ils servir de jetons secrets ?" }, a: { en: "They are unpredictable, since they come from the operating system's cryptographic random source rather than Math.random(). But identifiers tend to leak — into URLs, logs, referrer headers and analytics — so treat a UUID as an identifier that happens to be unguessable, not as a credential. Anything granting access deserves a dedicated token with an expiry.", fr: "Ils sont imprévisibles, puisqu'ils proviennent de la source aléatoire cryptographique du système d'exploitation et non de Math.random(). Mais un identifiant a tendance à fuiter — dans les URL, les logs, les en-têtes de référent et les outils d'analyse : considérez un UUID comme un identifiant qui se trouve être indevinable, pas comme un justificatif. Tout ce qui donne un accès mérite un jeton dédié avec une expiration." } },
    { q: { en: "Is a UUID a good primary key?", fr: "Un UUID est-il une bonne clé primaire ?" }, a: { en: "Often yes, with one caveat. Version 4 is random, so consecutive inserts land at unrelated positions in the index; on a clustered index — the default in InnoDB and SQL Server — that fragments pages and slows bulk insertion compared with a sequential integer. If insert throughput is your bottleneck, look at a time-ordered variant instead.", fr: "Souvent oui, avec une réserve. La version 4 est aléatoire : des insertions consécutives atterrissent à des positions sans rapport dans l'index, et sur un index clusterisé — le défaut d'InnoDB et de SQL Server — cela fragmente les pages et ralentit l'insertion en masse par rapport à un entier séquentiel. Si le débit d'insertion est votre goulot d'étranglement, regardez plutôt une variante ordonnée dans le temps." } },
  ],
  "cron-generator": [{ q: { en: "Does it support shortcuts like @daily or @hourly?", fr: "Supporte-t-il les raccourcis comme @daily ou @hourly ?" }, a: { en: "No. This builder works on the standard five-field syntax only, and rejects anything that is not five fields. The shortcuts are a convention of some cron implementations rather than part of the syntax itself — @daily is simply 0 0 * * *, and @hourly is 0 * * * *, both of which you can enter directly.", fr: "Non. Ce générateur ne travaille que sur la syntaxe standard à cinq champs et rejette tout ce qui n'en compte pas cinq. Ces raccourcis sont une convention de certaines implémentations de cron plutôt qu'un élément de la syntaxe — @daily équivaut simplement à 0 0 * * *, et @hourly à 0 * * * *, que vous pouvez saisir directement." } },
    { q: { en: "Why did my job run on the wrong day?", fr: "Pourquoi ma tâche s'est-elle exécutée le mauvais jour ?" }, a: { en: "Probably because you set both the day-of-month and the day-of-week field. Unlike the others, those two are combined with a logical or in most cron implementations: the job runs when either matches, not when both do. Constrain one and leave the other as an asterisk.", fr: "Probablement parce que vous avez renseigné à la fois le champ jour du mois et le champ jour de la semaine. Contrairement aux autres, ces deux-là se combinent par un ou logique dans la plupart des implémentations : la tâche s'exécute dès que l'un correspond, et non quand les deux correspondent. Contraignez l'un et laissez l'autre à l'astérisque." } },
    { q: { en: "Which time zone does a cron expression use?", fr: "Quel fuseau horaire utilise une expression cron ?" }, a: { en: "None of its own — it is interpreted in the time zone of the system running it, which is why the same line fires at different moments on a laptop in local time and a server in UTC. Daylight saving makes it concrete: a job set for a time that a spring transition skips does not run at all, and runs twice when autumn repeats the hour.", fr: "Aucun en propre — elle est interprétée dans le fuseau du système qui l'exécute, d'où le déclenchement à des moments différents entre un portable en heure locale et un serveur en UTC. L'heure d'été le rend concret : une tâche calée sur une heure que la transition de printemps supprime ne s'exécute pas du tout, et s'exécute deux fois quand l'automne répète cette heure." } },
    { q: { en: "How do I run something every fifteen minutes?", fr: "Comment exécuter quelque chose toutes les quinze minutes ?" }, a: { en: "Use a step in the minute field: */15 * * * *. The slash sets an interval, so */15 means every fifteenth minute starting at zero. The same notation works in the other fields — */2 in the hour field means every second hour.", fr: "Utilisez un pas dans le champ des minutes : */15 * * * *. La barre oblique définit un intervalle, donc */15 signifie toutes les quinze minutes à partir de zéro. La même notation fonctionne dans les autres champs — */2 dans le champ des heures signifie toutes les deux heures." } },
  ],
  "case-converter": [{ q: { en: "What case formats are available?", fr: "Quels formats de casse sont disponibles ?" }, a: { en: "Seven: UPPER CASE, lower case, Title Case, camelCase, PascalCase, snake_case and kebab-case. There is no separate Sentence case — Title Case capitalises every word, so a one-sentence input needs a manual fix on the words that should stay lowercase.", fr: "Sept : MAJUSCULE, minuscule, Titre, camelCase, PascalCase, snake_case et kebab-case. Il n'y a pas de format Phrase distinct — le format Titre capitalise chaque mot, donc une phrase demande une retouche manuelle sur les mots qui doivent rester en minuscules." } },
    { q: { en: "How does it know where words start in camelCase?", fr: "Comment repère-t-il le début des mots en camelCase ?" }, a: { en: "It looks for three signals: a lowercase letter immediately followed by an uppercase one, any run of underscores or hyphens, and whitespace. That is what lets the same input arrive as camelCase, snake_case or an ordinary sentence and convert correctly either way.", fr: "Il s'appuie sur trois signaux : une minuscule immédiatement suivie d'une majuscule, toute suite de tirets bas ou de traits d'union, et les espaces. C'est ce qui permet à une même entrée d'arriver en camelCase, en snake_case ou en phrase ordinaire et d'être convertie correctement dans tous les cas." } },
    { q: { en: "Why did my acronym lose its capitals?", fr: "Pourquoi mon acronyme a-t-il perdu ses majuscules ?" }, a: { en: "Consecutive capitals carry no word boundary, so an acronym is treated as one word and lowercased before being recapitalised — an identifier containing URL comes back as Url in Title Case. It also means APIKey splits into a single word and yields apikey rather than apiKey. Check the output when acronym casing matters.", fr: "Des majuscules consécutives ne portent aucune frontière de mot : un acronyme est donc traité comme un seul mot, mis en minuscules puis recapitalisé — un identifiant contenant URL ressort en Url au format Titre. Cela signifie aussi que APIKey est vu comme un mot unique et donne apikey plutôt que apiKey. Vérifiez le résultat quand la casse des acronymes compte." } },
    { q: { en: "Which conversions can I safely reverse?", fr: "Quelles conversions puis-je inverser sans perte ?" }, a: { en: "Those between formats that mark their boundaries explicitly: snake_case, kebab-case, camelCase and PascalCase convert back and forth without loss. Title Case and plain sentences lose information, because a space cannot be distinguished from a separator that used to be an underscore.", fr: "Celles entre formats qui marquent explicitement leurs frontières : snake_case, kebab-case, camelCase et PascalCase se convertissent dans les deux sens sans perte. Le format Titre et les phrases ordinaires perdent de l'information, car on ne peut plus distinguer une espace d'un séparateur qui était auparavant un tiret bas." } },
  ],
  "word-counter": [{ q: { en: "How is reading time estimated?", fr: "Comment le temps de lecture est-il estimé ?" }, a: { en: "At 238 words per minute — the average for adult silent reading found by Brysbaert's 2019 meta-analysis of more than a hundred studies. It is an order of magnitude, not a promise: dense technical text reads much slower, and reading aloud is closer to 150.", fr: "À 238 mots par minute — la moyenne de lecture silencieuse chez l'adulte établie par la méta-analyse de Brysbaert (2019), qui couvre plus d'une centaine d'études. C'est un ordre de grandeur, pas une promesse : un texte technique dense se lit bien plus lentement, et la lecture à voix haute tourne plutôt autour de 150." } },
    { q: { en: "How is a word counted exactly?", fr: "Comment un mot est-il compté exactement ?" }, a: { en: "Through the browser's Unicode word segmentation — the same rules that decide what a double-click selects — rather than by splitting on spaces. That matters for hyphenated compounds and apostrophes, and it is the only approach that gives a meaningful count for Chinese, Japanese or Thai, which do not separate words with spaces.", fr: "Par la segmentation Unicode du navigateur — les règles mêmes qui décident de ce qu'un double-clic sélectionne — plutôt qu'en découpant sur les espaces. Cela compte pour les composés à trait d'union et les apostrophes, et c'est la seule approche donnant un résultat pertinent pour le chinois, le japonais ou le thaï, qui ne séparent pas les mots par des espaces." } },
    { q: { en: "Why is the sentence count different from my word processor?", fr: "Pourquoi le nombre de phrases diffère-t-il de mon traitement de texte ?" }, a: { en: "Sentences are detected by looking for full stops, exclamation marks and question marks, a heuristic that is right most of the time and predictably wrong around abbreviations, decimal numbers, ellipses and domain names — each of those adds a sentence that is not there. Word and character counts are not affected.", fr: "Les phrases sont détectées en repérant points, points d'exclamation et points d'interrogation, une heuristique juste la plupart du temps et prévisiblement fausse autour des abréviations, nombres décimaux, points de suspension et noms de domaine — chacun ajoute une phrase qui n'existe pas. Les comptes de mots et de caractères n'en sont pas affectés." } },
    { q: { en: "Should I use the word count or the character count for a length limit?", fr: "Pour une limite de longueur, faut-il se fier aux mots ou aux caractères ?" }, a: { en: "Characters, in nearly every case. Meta descriptions, social posts and form fields express their limits in characters, and the count here is exact rather than heuristic. Both variants are shown, with and without spaces, because platforms disagree on which one they enforce.", fr: "Aux caractères, dans la quasi-totalité des cas. Meta descriptions, publications sociales et champs de formulaire expriment leurs limites en caractères, et le compte est ici exact plutôt qu'heuristique. Les deux variantes sont affichées, avec et sans espaces, parce que les plateformes ne s'accordent pas sur celle qu'elles appliquent." } },
  ],
  "remove-linebreaks": [{ q: { en: "Can I preserve paragraph breaks while removing single line breaks?", fr: "Puis-je conserver les sauts de paragraphe tout en supprimant les sauts de ligne simples ?" }, a: { en: "Yes — the tool preserves double line breaks (paragraph separators) while removing single ones.", fr: "Oui — l'outil conserve les doubles sauts de ligne (séparateurs de paragraphe) tout en supprimant les simples." } },
    { q: { en: "Which mode should I use for text copied from a PDF?", fr: "Quel mode utiliser pour un texte copié depuis un PDF ?" }, a: { en: "Normalize, in almost every case. It treats a blank line as a paragraph separator, unwraps the lines inside each paragraph and keeps the paragraphs apart — which is what a PDF's layout-driven line endings need. The join mode would collapse the whole document into a single block.", fr: "La normalisation, dans la quasi-totalité des cas. Elle traite une ligne vide comme un séparateur de paragraphe, déplie les lignes à l'intérieur de chaque paragraphe et conserve les paragraphes distincts — exactement ce qu'exigent des fins de ligne dictées par la mise en page. Le mode espace, lui, réduirait tout le document à un seul bloc." } },
    { q: { en: "Does it fix words split by a hyphen at the end of a line?", fr: "Répare-t-il les mots coupés par un trait d'union en fin de ligne ?" }, a: { en: "No. Only the line break is removed; the hyphen stays where it was, so a word broken across two PDF lines still needs a manual fix. Rejoining those automatically would be guesswork, since a hyphen may equally belong to a genuine compound word.", fr: "Non. Seul le saut de ligne est retiré ; le trait d'union reste en place, si bien qu'un mot coupé sur deux lignes de PDF demande encore une correction manuelle. Les recoller automatiquement relèverait de la devinette, puisqu'un trait d'union peut tout aussi bien appartenir à un vrai mot composé." } },
    { q: { en: "What is the difference between the join and strip modes?", fr: "Quelle différence entre le mode espace et le mode suppression ?" }, a: { en: "Join puts a space where each break was and collapses repeated spaces, which is right when the breaks fall between words. Strip removes them without substitution, which is right when a break falls inside a word. Choosing the wrong one either glues two words together or leaves a gap in the middle of one.", fr: "Le mode espace insère une espace à la place de chaque saut et fusionne les espaces répétées, ce qui convient quand les sauts tombent entre les mots. Le mode suppression les retire sans rien mettre à la place, ce qui convient quand un saut tombe au milieu d'un mot. Se tromper de mode colle deux mots ensemble ou laisse un blanc au milieu d'un seul." } },
  ],
  "text-reverser": [{ q: { en: "Does it handle emojis and Unicode correctly?", fr: "Gère-t-il correctement les emojis et l'Unicode ?" }, a: { en: "Yes — it uses proper Unicode segmentation so emojis and combining characters are treated as single units.", fr: "Oui — il utilise une segmentation Unicode correcte pour que les emojis et les caractères combinants soient traités comme des unités simples." } },
    { q: { en: "Why does reversed Arabic or Hebrew look wrong?", fr: "Pourquoi le texte arabe ou hébreu inversé paraît-il faux ?" }, a: { en: "Because those scripts are stored in reading order and reordered for display by the browser's bidirectional algorithm. Reversing the stored string gives the display algorithm a sequence it then rearranges again, so the result rarely matches what you pictured. For a mirrored visual effect, use a CSS transform rather than reversing the text itself.", fr: "Parce que ces écritures sont stockées dans l'ordre de lecture puis réordonnées à l'affichage par l'algorithme bidirectionnel du navigateur. Inverser la chaîne stockée fournit à cet algorithme une séquence qu'il réarrange à nouveau : le résultat correspond rarement à ce que vous imaginiez. Pour un effet visuel en miroir, utilisez une transformation CSS plutôt que d'inverser le texte." } },
    { q: { en: "What exactly do the three modes do?", fr: "Que font exactement les trois modes ?" }, a: { en: "Character mode reverses everything end to end, so the last line becomes the first. Word mode reverses the order of words inside each line and leaves the lines in place. Line mode reverses the order of the lines and leaves each line's contents untouched. Applying any mode twice returns the original exactly.", fr: "Le mode caractère inverse tout de bout en bout : la dernière ligne devient donc la première. Le mode mot inverse l'ordre des mots à l'intérieur de chaque ligne et laisse les lignes en place. Le mode ligne inverse l'ordre des lignes et laisse intact le contenu de chacune. Appliquer deux fois n'importe quel mode restitue exactement l'original." } },
  ],
  "url-encoder": [{ q: { en: "Can I paste a whole URL into it?", fr: "Puis-je y coller une URL entière ?" }, a: { en: "You can, but the result will not be a usable link. This tool does component encoding: it escapes every reserved character, slashes and colons included, which is correct for a value going inside a URL and wrong for the URL itself. Encode the individual parts, then assemble the address around them.", fr: "Vous pouvez, mais le résultat ne sera pas un lien utilisable. Cet outil fait de l'encodage de composant : il échappe tout caractère réservé, barres obliques et deux-points compris, ce qui est correct pour une valeur destinée à entrer dans une URL et faux pour l'URL elle-même. Encodez les morceaux séparément, puis assemblez l'adresse autour d'eux." } },
    { q: { en: "Why is a space sometimes %20 and sometimes a plus sign?", fr: "Pourquoi une espace est-elle tantôt %20, tantôt un signe plus ?" }, a: { en: "The plus form comes from HTML form submission, whose media type predates the modern URL specification and encodes spaces that way inside a query string. It is valid there and only there: in a path segment a plus sign means a literal plus, not a space. This tool always produces %20, which is correct in every position.", fr: "La forme plus vient de la soumission de formulaire HTML, dont le type de média est antérieur à la spécification moderne des URL et qui encode ainsi les espaces dans une query string. Elle est valide là, et seulement là : dans un segment de chemin, un signe plus désigne un vrai plus, pas une espace. Cet outil produit toujours %20, correct en toute position." } },
    { q: { en: "Which characters are left untouched?", fr: "Quels caractères restent intacts ?" }, a: { en: "Letters, digits, and the marks minus, underscore, dot, exclamation, tilde, asterisk, apostrophe and parentheses. Those are safe anywhere in a URL, so encoding them would add noise without adding safety. Everything else, including the space and all non-ASCII characters, is percent-encoded.", fr: "Les lettres, les chiffres, et les signes moins, tiret bas, point, point d'exclamation, tilde, astérisque, apostrophe et parenthèses. Ceux-là sont sûrs partout dans une URL : les encoder ajouterait du bruit sans ajouter de sécurité. Tout le reste, y compris l'espace et l'ensemble des caractères non ASCII, est percent-encodé." } },
    { q: { en: "Why does one accented letter produce several % groups?", fr: "Pourquoi une lettre accentuée produit-elle plusieurs groupes % ?" }, a: { en: "Because percent-encoding works on bytes, not characters. A non-ASCII character is first encoded as UTF-8, which uses two to four bytes, and each byte becomes its own percent group. That is why é gives %C3%A9 and an emoji gives four groups.", fr: "Parce que le percent-encoding travaille sur des octets, pas sur des caractères. Un caractère non ASCII est d'abord encodé en UTF-8, ce qui occupe deux à quatre octets, et chaque octet devient son propre groupe pourcent. D'où é qui donne %C3%A9 et un emoji qui en donne quatre." } },
  ],
  "html-entities": [{ q: { en: "Which characters get encoded?", fr: "Quels caractères sont encodés ?" }, a: { en: "The five structural ones are always escaped — ampersand, less-than, greater-than, double quote and apostrophe — along with everything above plain ASCII. A named entity is used when HTML 4 defines one, so é becomes &eacute;; anything else falls back to a decimal reference, which is why an emoji comes out as &#128512;.", fr: "Les cinq caractères structurants sont toujours échappés — esperluette, inférieur, supérieur, guillemet double et apostrophe — ainsi que tout ce qui dépasse l'ASCII simple. Une entité nommée est utilisée quand HTML 4 en définit une, si bien que é devient &eacute; ; le reste bascule sur une référence décimale, d'où un emoji rendu en &#128512;." } },
    { q: { en: "Does escaping entities protect me from XSS?", fr: "Échapper les entités me protège-t-il des failles XSS ?" }, a: { en: "Only in the right context, and only for quoted attributes. Escaping is correct for text between tags and for attribute values that are wrapped in quotes. Inside a script block, a URL or a CSS rule it does nothing useful — each needs its own escaping — and against an unquoted attribute it is no defence at all, since a space alone is enough to inject one.", fr: "Seulement dans le bon contexte, et seulement pour des attributs entre guillemets. L'échappement est correct pour du texte entre balises et pour des valeurs d'attribut encadrées de guillemets. Dans un bloc script, une URL ou une règle CSS, il ne sert à rien — chacun réclame son propre échappement — et face à un attribut sans guillemets il ne protège pas du tout, puisqu'une simple espace suffit à en injecter un." } },
    { q: { en: "Why does my emoji become a number instead of a name?", fr: "Pourquoi mon emoji devient-il un nombre plutôt qu'un nom ?" }, a: { en: "Because it has no name. Named entities come from a fixed list defined by HTML 4, which covers Latin-1 letters, common punctuation, currency symbols and Greek. Emoji were added to Unicode long afterwards and never received names, so they are written as a decimal reference instead. Both forms display identically in a browser.", fr: "Parce qu'il n'en a pas. Les entités nommées proviennent d'une liste figée définie par HTML 4, qui couvre les lettres Latin-1, la ponctuation courante, les symboles monétaires et le grec. Les emojis ont été ajoutés à Unicode bien plus tard et n'ont jamais reçu de nom : ils s'écrivent donc en référence décimale. Les deux formes s'affichent à l'identique dans un navigateur." } },
    { q: { en: "What is the difference between a non-breaking space and a normal one?", fr: "Quelle différence entre une espace insécable et une espace normale ?" }, a: { en: "A non-breaking space, written &nbsp;, looks like a space but forbids a line break at that point and is not collapsed with neighbouring whitespace the way an ordinary space is. It is the right character between a number and its unit, or before a French colon. Used as a layout tool to push text around, it is a poor substitute for CSS margins.", fr: "Une espace insécable, écrite &nbsp;, ressemble à une espace mais interdit un retour à la ligne à cet endroit et n'est pas fusionnée avec les espaces voisines comme le serait une espace ordinaire. C'est le bon caractère entre un nombre et son unité, ou devant un deux-points en français. Employée comme outil de mise en page pour décaler du texte, elle remplace mal une marge CSS." } },
  ],
  "palette-generator": [
    { q: { en: "Why do all the colors look the same when I start from grey?", fr: "Pourquoi toutes les couleurs se ressemblent-elles quand je pars d'un gris ?" }, a: { en: "Because harmonies work by rotating the hue, and a grey, black or white has no saturation, so rotating its hue changes nothing. You'll only get the lighter and darker variants. Pick a base color with some saturation.", fr: "Parce que les harmonies font tourner la teinte, et qu'un gris, un noir ou un blanc n'a pas de saturation : faire tourner sa teinte ne change rien. Vous n'obtiendrez que les variantes claires et foncées. Choisissez une couleur de base un peu saturée." } },
    { q: { en: "Which harmony should I use for a website?", fr: "Quelle harmonie choisir pour un site web ?" }, a: { en: "Often none of them as a full set. A single accent color with neutral greys covers most interfaces. Analogous palettes stay calm and suit backgrounds or illustrations, while complementary and triadic ones give strong contrast, useful when a few elements such as chart series must be told apart at a glance.", fr: "Souvent, aucune comme jeu complet. Une seule couleur d'accent avec des gris neutres couvre la plupart des interfaces. Les palettes analogues restent calmes et conviennent aux fonds ou aux illustrations, tandis que les complémentaires et triadiques donnent un contraste fort, utile quand quelques éléments, comme les séries d'un graphique, doivent se distinguer d'un coup d'œil." } },
    { q: { en: "Can I enter my base color in RGB or HSL?", fr: "Puis-je saisir ma couleur de base en RGB ou en HSL ?" }, a: { en: "Not directly: the field takes a hex code, with or without the #, or you can use the color picker. To convert an RGB or HSL value first, use the color picker tool, which shows every format for the same color.", fr: "Pas directement : le champ accepte un code hexadécimal, avec ou sans #, ou vous pouvez passer par le sélecteur de couleur. Pour convertir d'abord une valeur RGB ou HSL, utilisez l'outil sélecteur de couleur, qui affiche tous les formats d'une même couleur." } },
    { q: { en: "Are the generated colors accessible?", fr: "Les couleurs générées sont-elles accessibles ?" }, a: { en: "Not automatically. The harmonies keep the same HSL lightness, but perceived brightness varies a lot between hues, so text contrast can pass on one color and fail on the next. Check each text and background pair against the WCAG ratios with the contrast checker.", fr: "Pas automatiquement. Les harmonies gardent la même luminosité HSL, mais la clarté perçue varie beaucoup d'une teinte à l'autre : le contraste d'un texte peut passer sur une couleur et échouer sur la suivante. Vérifiez chaque couple texte et fond avec le vérificateur de contraste, selon les ratios WCAG." } },
  ],
  "password-generator": [
    { q: { en: "Is the password generated on your server?", fr: "Le mot de passe est-il généré sur votre serveur ?" }, a: { en: "No. It's drawn in your browser with the Web Crypto API after the page loads. It isn't sent anywhere, isn't stored, and doesn't appear in the page's HTML.", fr: "Non. Il est tiré dans votre navigateur avec la Web Crypto API, une fois la page chargée. Il n'est envoyé nulle part, n'est pas conservé et n'apparaît pas dans le HTML de la page." } },
    { q: { en: "How long should a password be?", fr: "Quelle longueur choisir pour un mot de passe ?" }, a: { en: "Sixteen characters of letters and digits (95 bits) is a strong default for accounts you store in a password manager. For server and application secrets, which nobody types, use 24 or 32 characters. Length adds more strength than symbols do.", fr: "Seize caractères de lettres et chiffres (95 bits) est un bon choix par défaut pour les comptes enregistrés dans un gestionnaire de mots de passe. Pour les secrets de serveur et d'application, que personne ne tape, prenez 24 ou 32 caractères. La longueur apporte plus de solidité que les symboles." } },
    { q: { en: "Why avoid symbols in a database password?", fr: "Pourquoi éviter les symboles dans un mot de passe de base de données ?" }, a: { en: "Because characters such as @, :, $ and # have a meaning in connection strings, shells and .env files, and break the configuration unless they're escaped. A longer password made of letters and digits is just as strong and causes no escaping problems.", fr: "Parce que des caractères comme @, :, $ et # ont un sens dans les chaînes de connexion, les shells et les fichiers .env, et cassent la configuration s'ils ne sont pas échappés. Un mot de passe plus long en lettres et chiffres est tout aussi solide et n'impose aucun échappement." } },
    { q: { en: "Will each password contain a digit and a symbol if I tick them?", fr: "Chaque mot de passe contiendra-t-il un chiffre et un symbole si je les coche ?" }, a: { en: "Yes. Every ticked family appears at least once in each password, so they pass sign-up forms that require one of each. Lowercase letters are always included.", fr: "Oui. Chaque famille cochée apparaît au moins une fois dans chaque mot de passe, pour passer les formulaires d'inscription qui en exigent un de chaque. Les minuscules sont toujours incluses." } },
    { q: { en: "What does \"no ambiguous\" remove?", fr: "Que retire l'option « sans ambigus » ?" }, a: { en: "The characters l, 1, I, O, 0, B and 8, which are easy to mix up when reading a password aloud, from a screen or from paper. Use it for passwords that people will type by hand, and add a character or two to keep the same strength.", fr: "Les caractères l, 1, I, O, 0, B et 8, faciles à confondre quand on lit un mot de passe à voix haute, à l'écran ou sur papier. Utilisez-la pour les mots de passe que des personnes taperont à la main, et ajoutez un ou deux caractères pour garder la même solidité." } },
  ],
  "gradient-generator": [{ q: { en: "How many color stops can I add?", fr: "Combien d'arrêts de couleur puis-je ajouter ?" }, a: { en: "Up to 5 color stops — enough to create rich, multi-tone gradients.", fr: "Jusqu'à 5 arrêts de couleur — suffisant pour créer des dégradés riches à plusieurs tons." } },
    { q: { en: "Why does my blue-to-yellow gradient go grey in the middle?", fr: "Pourquoi mon dégradé bleu vers jaune devient-il gris au milieu ?" }, a: { en: "Because browsers interpolate in sRGB channel by channel, and the arithmetic midpoint between two opposite hues lands near grey. Add a third stop in the middle, in the hue you actually want, and the dull band disappears. Modern CSS can also name a different interpolation space such as Oklab, but support is more recent than this syntax.", fr: "Parce que les navigateurs interpolent en sRGB canal par canal, et que le milieu arithmétique entre deux teintes opposées tombe près du gris. Ajoutez un troisième arrêt au centre, dans la teinte réellement voulue, et la bande terne disparaît. Le CSS moderne permet aussi de nommer un autre espace d'interpolation comme Oklab, mais son support est plus récent que cette syntaxe." } },
    { q: { en: "Which way does the angle point?", fr: "Dans quel sens pointe l'angle ?" }, a: { en: "Clockwise from straight up, in the direction the gradient travels. So 0 degrees runs bottom to top, 90 degrees left to right, and 180 degrees top to bottom. It catches people out because most maths conventions start from the horizontal and turn the other way.", fr: "Dans le sens horaire depuis la verticale vers le haut, dans la direction que suit le dégradé. Ainsi 0 degré va de bas en haut, 90 degrés de gauche à droite, et 180 degrés de haut en bas. Cela surprend parce que la plupart des conventions mathématiques partent de l'horizontale et tournent dans l'autre sens." } },
    { q: { en: "When should I use a conic gradient?", fr: "Quand utiliser un dégradé conique ?" }, a: { en: "When the colour should sweep around a centre rather than along a line — pie charts, colour wheels, and progress rings are the usual cases, all achievable in pure CSS with no image or canvas. A radial gradient spreads outward from a point instead, which suits spotlights and vignettes.", fr: "Quand la couleur doit balayer autour d'un centre plutôt que suivre une ligne — camemberts, roues chromatiques et anneaux de progression en sont les usages habituels, tous réalisables en CSS pur sans image ni canvas. Un dégradé radial, lui, se diffuse depuis un point, ce qui convient aux halos et aux vignettages." } },
  ],
  "meta-preview": [
    { q: { en: "I changed my og:image but LinkedIn or Facebook still shows the old one. Why?", fr: "J'ai changé mon og:image mais LinkedIn ou Facebook affiche toujours l'ancienne. Pourquoi ?" }, a: { en: "Because both networks keep their own copy of the preview from the first time the URL was shared. Paste the URL into Facebook's Sharing Debugger (Scrape Again) or LinkedIn's Post Inspector to make them fetch the page again. If this tool already shows the new image, your page is fine and only their copy is out of date.", fr: "Parce que les deux réseaux gardent leur propre copie de l'aperçu depuis le premier partage de l'URL. Collez l'URL dans le Sharing Debugger de Facebook (Scrape Again) ou le Post Inspector de LinkedIn pour qu'ils récupèrent à nouveau la page. Si cet outil affiche déjà la nouvelle image, votre page est correcte et seule leur copie est périmée." } },
    { q: { en: "What size should my og:image be?", fr: "Quelle taille donner à mon og:image ?" }, a: { en: "1200 × 630 pixels, a 1.91:1 ratio, is the safe choice: it fills the large card on Facebook, LinkedIn and X. Use an absolute https:// URL and a JPG or PNG. This tool checks that the tag is there and that the URL is absolute, but it doesn't measure the image itself.", fr: "1200 × 630 pixels, soit un ratio de 1,91:1, est le choix sûr : il remplit la grande carte sur Facebook, LinkedIn et X. Utilisez une URL absolue en https:// et un JPG ou un PNG. Cet outil vérifie que la balise existe et que l'URL est absolue, mais ne mesure pas l'image elle-même." } },
    { q: { en: "Do I need twitter: tags if I already have Open Graph tags?", fr: "Faut-il des balises twitter: si j'ai déjà les balises Open Graph ?" }, a: { en: "Mostly not. X falls back to og:title, og:description and og:image when the matching twitter: tags are absent. The one worth adding is twitter:card, because it has no Open Graph equivalent and decides between the small and the large card layout.", fr: "En grande partie, non. X se rabat sur og:title, og:description et og:image quand les balises twitter: correspondantes manquent. Celle qui vaut la peine est twitter:card, car elle n'a pas d'équivalent Open Graph et décide entre la petite et la grande mise en page." } },
    { q: { en: "Why does the Google preview show a different title from the Facebook card?", fr: "Pourquoi l'aperçu Google affiche-t-il un autre titre que la carte Facebook ?" }, a: { en: "Because they read different tags: Google uses the title tag, Facebook uses og:title. Having two different wordings is fine and often useful, a search title aimed at the query and a social title aimed at the click, as long as both describe the same page.", fr: "Parce qu'ils lisent des balises différentes : Google utilise la balise title, Facebook utilise og:title. Avoir deux formulations est normal et souvent utile, un titre de recherche tourné vers la requête et un titre social tourné vers le clic, tant que les deux décrivent la même page." } },
    { q: { en: "My tags are added with JavaScript. Why doesn't the tool find them?", fr: "Mes balises sont ajoutées en JavaScript. Pourquoi l'outil ne les trouve-t-il pas ?" }, a: { en: "Because it reads the HTML the server returns, like the crawlers of social networks, which generally don't run scripts. If the tool can't see the tags, a shared link most likely won't show them either. Generate them on the server or pre-render the page.", fr: "Parce qu'il lit le HTML renvoyé par le serveur, comme les robots des réseaux sociaux, qui n'exécutent généralement pas les scripts. Si l'outil ne voit pas les balises, un lien partagé ne les affichera très probablement pas non plus. Générez-les côté serveur ou pré-rendez la page." } },
  ],
  "seo-analyzer": [
    { q: { en: "Why is my score different from Semrush, SE Ranking or other SEO checkers?", fr: "Pourquoi mon score diffère-t-il de Semrush, SE Ranking ou d'autres outils SEO ?" }, a: { en: "Because each tool picks its own checks and weights. Some run a hundred or more tests, including speed and structured data; this one runs eleven, with the point values described on this page. Compare the list of problems each tool finds rather than the two numbers.", fr: "Parce que chaque outil choisit ses propres contrôles et leur poids. Certains lancent une centaine de tests ou plus, vitesse et données structurées comprises ; celui-ci en lance onze, avec le barème décrit sur cette page. Comparez la liste des problèmes trouvés par chaque outil plutôt que les deux chiffres." } },
    { q: { en: "The report says my title or text is missing, but I can see it on the page. Why?", fr: "Le rapport dit que mon titre ou mon texte manque, alors que je le vois sur la page. Pourquoi ?" }, a: { en: "Your site most likely builds that content with JavaScript after the page loads. The analyzer reads the HTML the server sends, as a basic crawler would, and doesn't run scripts. Check the page source (Ctrl+U): if the text isn't there, server-side rendering or pre-rendering will make it visible to every crawler.", fr: "Votre site construit très probablement ce contenu en JavaScript après le chargement. L'analyseur lit le HTML envoyé par le serveur, comme un robot simple, sans exécuter de scripts. Affichez le code source (Ctrl+U) : si le texte n'y est pas, un rendu côté serveur ou un pré-rendu le rendra visible pour tous les robots." } },
    { q: { en: "Does a score of 100 mean my page will rank?", fr: "Un score de 100 garantit-il un bon classement ?" }, a: { en: "No. It means the basic on-page tags are present and within range. Rankings depend on how well the content answers the search, on the site's authority and on many signals this tool doesn't measure. A clean 100 removes obstacles; it doesn't create demand.", fr: "Non. Il signifie que les balises on-page de base sont présentes et dans les bonnes plages. Le classement dépend de la façon dont le contenu répond à la recherche, de l'autorité du site et de nombreux signaux que cet outil ne mesure pas. Un 100 lève des obstacles ; il ne crée pas la demande." } },
    { q: { en: "Why is an image with alt=\"\" not counted as missing?", fr: "Pourquoi une image avec alt=\"\" n'est-elle pas comptée comme fautive ?" }, a: { en: "Because an empty alt is the correct markup for a decorative image: it tells screen readers to skip it. Only an image with no alt attribute at all is flagged. Images that carry information, like a chart or a product photo, still need a real description.", fr: "Parce qu'un alt vide est le balisage correct pour une image décorative : il indique aux lecteurs d'écran de l'ignorer. Seule une image sans aucun attribut alt est signalée. Les images porteuses d'information, comme un graphique ou une photo produit, ont toujours besoin d'une vraie description." } },
    { q: { en: "Why does a noindex give a red result?", fr: "Pourquoi un noindex donne-t-il un résultat rouge ?" }, a: { en: "Because a robots meta with noindex asks search engines to drop the page from their results, which undoes every other check. It's sometimes intended, on a thank-you page or an internal search page. When it isn't, it's usually a staging setting that followed the code to production.", fr: "Parce qu'une meta robots avec noindex demande aux moteurs de retirer la page de leurs résultats, ce qui annule tous les autres contrôles. C'est parfois voulu, sur une page de remerciement ou une page de recherche interne. Sinon, c'est en général un réglage de préproduction qui a suivi le code en production." } },
  ],
  "border-radius": [
    { q: { en: "Why does a 50% radius look oval instead of round?", fr: "Pourquoi un rayon à 50% donne une forme ovale et pas ronde ?" }, a: { en: "Because the percentage is computed against the element's own width for the horizontal radius and its own height for the vertical radius. On a square element both are equal, so you get a circle. On a rectangle they differ, so the corner curve becomes an ellipse.", fr: "Parce que le pourcentage se calcule par rapport à la largeur de l'élément pour le rayon horizontal, et à sa hauteur pour le rayon vertical. Sur un élément carré, les deux sont égaux, donc on obtient un cercle. Sur un rectangle, ils diffèrent, et la courbe du coin devient une ellipse." } },
    { q: { en: "Is border-radius the same as an iOS-style squircle icon?", fr: "border-radius produit-il la même courbe que les icônes squircle d'iOS ?" }, a: { en: "Not exactly. iOS app icons use a superellipse curve, which is mathematically smoother between the flat edge and the corner than a standard CSS border-radius arc. Border-radius gets visually close at high values but won't match pixel-for-pixel.", fr: "Pas exactement. Les icônes iOS utilisent une courbe superellipse, mathématiquement plus douce entre le bord plat et le coin qu'un arc CSS border-radius classique. border-radius s'en approche visuellement à forte valeur, mais sans correspondance pixel pour pixel." } },
  ],
  "timestamp": [
    { q: { en: "Why does my timestamp show a date thousands of years in the future?", fr: "Pourquoi mon timestamp affiche-t-il une date des milliers d'années dans le futur ?" }, a: { en: "You most likely pasted a millisecond timestamp (13 digits) into a field expecting seconds (10 digits). A millisecond value read as seconds is 1000× too large, which pushes the date far into the future. Divide it by 1000 first.", fr: "Vous avez probablement collé un timestamp en millisecondes (13 chiffres) dans un champ attendant des secondes (10 chiffres). Une valeur en millisecondes lue comme des secondes est 1000 fois trop grande, ce qui projette la date très loin dans le futur. Divisez-la d'abord par 1000." } },
    { q: { en: "Does the Unix timestamp have a maximum value like the Y2K bug?", fr: "Le timestamp Unix a-t-il une valeur maximale, comme le bug de l'an 2000 ?" }, a: { en: "Yes, but it doesn't affect this tool. Classic 32-bit signed Unix time overflows on January 19, 2038 — a real limit on some older C systems and pre-8.0 MySQL TIMESTAMP columns. JavaScript's Date object stores milliseconds as a 64-bit number, so timestamps here are safe well beyond that date.", fr: "Oui, mais ça n'affecte pas cet outil. Le temps Unix classique en 32 bits signés déborde le 19 janvier 2038 — une vraie limite sur certains vieux systèmes C et les colonnes MySQL TIMESTAMP antérieures à la version 8.0. L'objet Date de JavaScript stocke les millisecondes sur 64 bits, donc les timestamps ici restent fiables bien au-delà de cette date." } },
  ],
  "favicon-generator": [
    { q: { en: "Is the downloaded .ico file a real ICO format?", fr: "Le fichier .ico téléchargé est-il un vrai format ICO ?" }, a: { en: "No — it's a PNG image renamed with an .ico extension. Browsers read it correctly when linked with <link rel=\"icon\">, but if you need a true multi-size ICO container (some legacy Windows contexts require it), use a dedicated ICO packer instead.", fr: "Non — c'est une image PNG renommée avec l'extension .ico. Les navigateurs la lisent correctement via <link rel=\"icon\">, mais si vous avez besoin d'un vrai conteneur ICO multi-tailles (certains contextes Windows anciens l'exigent), utilisez un packer ICO dédié." } },
    { q: { en: "Can I use more than two characters?", fr: "Puis-je utiliser plus de deux caractères ?" }, a: { en: "The input is capped at two characters by design — favicons render at 16px in most browser tabs, and anything beyond two characters becomes unreadable at that size regardless of font weight.", fr: "La saisie est volontairement limitée à deux caractères — les favicons s'affichent à 16px dans la plupart des onglets de navigateur, et au-delà de deux caractères, le texte devient illisible à cette taille quelle que soit la graisse." } },
  ],
  "jwt-decoder": [
    { q: { en: "Does this tool verify if the JWT signature is valid?", fr: "Cet outil vérifie-t-il que la signature du JWT est valide ?" }, a: { en: "No, and that's intentional — verifying requires the secret key (HS256) or public key (RS256) used to sign the token, which this tool never asks for. It only decodes the header and payload so you can read the claims; treat an unverified token as untrusted.", fr: "Non, et c'est volontaire — la vérification nécessite la clé secrète (HS256) ou la clé publique (RS256) utilisée pour signer le token, que cet outil ne demande jamais. Il décode uniquement le header et le payload pour lire les claims ; considérez un token non vérifié comme non fiable." } },
    { q: { en: "Why does the tool show a sample token by default?", fr: "Pourquoi l'outil affiche-t-il un token d'exemple par défaut ?" }, a: { en: "It preloads the well-known jwt.io demo token (an HS256 token with sub, name and iat/exp claims) so you can see the decoded output immediately, without needing a real token on hand first.", fr: "Il précharge le token de démo connu de jwt.io (un token HS256 avec des claims sub, name et iat/exp) pour que vous voyiez le résultat décodé immédiatement, sans avoir besoin d'un vrai token sous la main." } },
  ],
  "robots-txt": [
    { q: { en: "Does Disallow in robots.txt actually hide a page from search results?", fr: "Une règle Disallow dans robots.txt masque-t-elle vraiment une page des résultats de recherche ?" }, a: { en: "Not reliably. A well-behaved crawler won't crawl the disallowed path, but the URL can still get indexed (without its content) if other sites link to it, and robots.txt itself is publicly readable — so a Disallow rule reveals the path rather than hiding it. Use noindex meta tags or authentication for pages that must stay out of results or off-limits.", fr: "Pas de façon fiable. Un crawler respectueux ne va pas explorer le chemin exclu, mais l'URL peut quand même être indexée (sans son contenu) si d'autres sites y font un lien, et robots.txt lui-même est lisible publiquement — une règle Disallow révèle donc le chemin plutôt que de le cacher. Utilisez une balise meta noindex ou une authentification pour les pages qui doivent vraiment rester hors des résultats ou inaccessibles." } },
    { q: { en: "Where does the finished robots.txt file need to go?", fr: "Où faut-il placer le fichier robots.txt une fois généré ?" }, a: { en: "At the root of the domain — https://example.com/robots.txt — not in a subdirectory. A file placed at https://example.com/blog/robots.txt is ignored by every major crawler; only the root location is checked.", fr: "À la racine du domaine — https://example.com/robots.txt — pas dans un sous-répertoire. Un fichier placé à https://example.com/blog/robots.txt est ignoré par tous les crawlers majeurs ; seul l'emplacement racine est vérifié." } },
  ],
  "base-converter": [
    { q: { en: "Can I convert negative numbers?", fr: "Puis-je convertir des nombres négatifs ?" }, a: { en: "No — the input is treated as an unsigned integer. There's no two's-complement handling, so a negative value won't produce the binary representation a programming language would generate internally.", fr: "Non — la saisie est traitée comme un entier non signé. Il n'y a pas de gestion du complément à deux, donc une valeur négative ne produira pas la représentation binaire qu'un langage de programmation générerait en interne." } },
    { q: { en: "Why does hex use letters A–F?", fr: "Pourquoi l'hexadécimal utilise-t-il les lettres A à F ?" }, a: { en: "Because base 16 needs sixteen distinct digits and decimal only supplies ten (0–9). A through F fill the remaining six values (10 through 15) — so hex FF equals decimal 255, the maximum value a single byte can hold.", fr: "Parce que la base 16 a besoin de seize chiffres distincts et le décimal n'en fournit que dix (0 à 9). A à F comblent les six valeurs restantes (10 à 15) — donc FF en hexadécimal équivaut à 255 en décimal, la valeur maximale qu'un seul octet peut contenir." } },
  ],
  "box-shadow": [
    { q: { en: "What does a negative spread value actually do?", fr: "Que fait réellement une valeur de spread négative ?" }, a: { en: "It shrinks the shadow's box before the blur is applied, pulling the shadow in tighter than the element itself. Combined with a larger blur, this is how you get a soft shadow that doesn't visibly extend past the element's edges.", fr: "Elle réduit la boîte de l'ombre avant que le flou ne soit appliqué, resserrant l'ombre plus près que l'élément lui-même. Combiné à un flou plus large, c'est ainsi qu'on obtient une ombre douce qui ne déborde pas visiblement des bords de l'élément." } },
    { q: { en: "Can I generate more than one shadow layer at once?", fr: "Puis-je générer plusieurs couches d'ombre en une fois ?" }, a: { en: "Not in a single pass — this tool builds one box-shadow value at a time. For a layered shadow (soft ambient + sharp contact shadow), generate each layer separately and join them with a comma in your CSS.", fr: "Pas en une seule passe — cet outil construit une valeur box-shadow à la fois. Pour une ombre en couches (ambiante douce + ombre de contact nette), générez chaque couche séparément et combinez-les avec une virgule dans votre CSS." } },
  ],
  "color-picker": [
    { q: { en: "What's the actual difference between HSL and HSV?", fr: "Quelle est la vraie différence entre HSL et HSV ?" }, a: { en: "Both describe hue, saturation and a third axis — but HSL's lightness goes from black to the pure color to white, while HSV's value goes from black to the pure color at full brightness, with saturation controlling how much white is mixed in. In practice, HSV tends to match how design tools like Photoshop let you darken a color without it turning gray.", fr: "Les deux décrivent la teinte, la saturation et un troisième axe — mais la luminosité (lightness) de HSL va du noir à la couleur pure jusqu'au blanc, tandis que la valeur de HSV va du noir à la couleur pure à pleine luminosité, la saturation contrôlant la quantité de blanc mélangée. En pratique, HSV correspond souvent à la façon dont des outils comme Photoshop permettent d'assombrir une couleur sans qu'elle vire au gris." } },
    { q: { en: "Does this tool support colors with transparency?", fr: "Cet outil gère-t-il les couleurs avec transparence ?" }, a: { en: "Not directly — the underlying browser color picker only handles opaque colors. Copy the HEX or RGB value from here and add the alpha channel yourself, either as an 8-digit hex or by switching to rgba()/hsla() syntax.", fr: "Pas directement — le sélecteur de couleur natif du navigateur ne gère que les couleurs opaques. Copiez la valeur HEX ou RGB depuis ici et ajoutez vous-même le canal alpha, soit en hexadécimal à 8 chiffres, soit en passant à la syntaxe rgba()/hsla()." } },
  ],
  "contrast-checker": [
    { q: { en: "What exactly counts as 'large text' for the relaxed 3:1 threshold?", fr: "Qu'est-ce qui compte exactement comme « grand texte » pour le seuil allégé de 3:1 ?" }, a: { en: "WCAG defines it precisely: 18pt (24px) at regular weight, or 14pt (about 18.66px) at bold weight, and nothing smaller. A 22px regular paragraph doesn't qualify — it still needs the full 4.5:1 ratio.", fr: "Le WCAG le définit précisément : 18pt (24px) en graisse normale, ou 14pt (environ 18,66px) en gras, rien de plus petit. Un paragraphe en 22px normal n'est pas éligible — il a toujours besoin du ratio complet de 4,5:1." } },
    { q: { en: "My colors pass AA — does that mean the design is accessible?", fr: "Mes couleurs passent AA — est-ce que ça veut dire que le design est accessible ?" }, a: { en: "It means this one specific check passes. Contrast ratio is one WCAG success criterion among many — color-blindness-safe palettes, focus indicators, and text spacing are separate requirements this tool doesn't check.", fr: "Ça veut dire que ce critère précis est validé. Le ratio de contraste est un critère de succès WCAG parmi beaucoup d'autres — palettes adaptées au daltonisme, indicateurs de focus, espacement du texte sont des exigences séparées que cet outil ne vérifie pas." } },
  ],
  "css-grid": [
    { q: { en: "Can this generator create a layout with a fixed sidebar and flexible content area?", fr: "Ce générateur peut-il créer une mise en page avec une barre latérale fixe et une zone de contenu flexible ?" }, a: { en: "Not directly — it only outputs uniform tracks via repeat(count, size), so every column or row in a given axis shares the same size. For a mixed layout like grid-template-columns: 240px 1fr 240px, copy the base output and edit the template-columns line by hand.", fr: "Pas directement — il ne produit que des pistes uniformes via repeat(count, size), donc chaque colonne ou ligne d'un axe partage la même taille. Pour une mise en page mixte comme grid-template-columns: 240px 1fr 240px, copiez le résultat de base et modifiez la ligne template-columns à la main." } },
    { q: { en: "Why use fr instead of percentages for column widths?", fr: "Pourquoi utiliser fr plutôt que des pourcentages pour la largeur des colonnes ?" }, a: { en: "Percentages are calculated against the container's total width, which gets complicated once gap is involved — gap space still has to come from somewhere. Fr units divide up only the leftover space after gaps and fixed tracks are already accounted for, so the math stays correct automatically.", fr: "Les pourcentages se calculent par rapport à la largeur totale du conteneur, ce qui se complique dès que le gap entre en jeu — cet espace doit bien venir de quelque part. Les unités fr ne divisent que l'espace restant une fois le gap et les pistes fixes déjà pris en compte, donc le calcul reste juste automatiquement." } },
  ],
  "css-minifier": [
    { q: { en: "Is this as safe as a build-tool minifier like cssnano?", fr: "Est-ce aussi fiable qu'un minificateur intégré à un build comme cssnano ?" }, a: { en: "For typical stylesheets, yes — comments, whitespace and redundant semicolons are removed the same way. The one edge case to watch: this tool uses text patterns rather than a real CSS parser, so a semicolon or brace inside a quoted string value could theoretically be altered. That's rare in practice but worth a visual check on unusual CSS.", fr: "Pour des feuilles de style classiques, oui — commentaires, espaces et points-virgules redondants sont retirés de la même façon. Le cas particulier à surveiller : cet outil utilise des motifs de texte plutôt qu'un vrai parseur CSS, donc un point-virgule ou une accolade dans une valeur de chaîne entre guillemets pourrait théoriquement être altéré. C'est rare en pratique, mais mérite une vérification visuelle sur du CSS inhabituel." } },
    { q: { en: "How much size reduction should I expect?", fr: "À quelle réduction de taille dois-je m'attendre ?" }, a: { en: "It depends entirely on the source — a heavily commented, indented stylesheet can shrink 30–40%, while CSS that's already tightly written might only drop 10–15%. The exact before/after character counts are shown under the output so you don't have to guess.", fr: "Ça dépend entièrement de la source — une feuille de style très commentée et indentée peut perdre 30 à 40%, tandis qu'un CSS déjà écrit de façon compacte ne baissera peut-être que de 10 à 15%. Le nombre exact de caractères avant/après est affiché sous le résultat, pas besoin de deviner." } },
  ],
  "csv-json": [
    { q: { en: "Does the CSV parser handle commas inside quoted fields correctly?", fr: "Le parseur CSV gère-t-il correctement les virgules à l'intérieur de champs entre guillemets ?" }, a: { en: "No — it splits every line on commas regardless of quoting, so a value like \"Doe, John\" inside quotes will be split into two columns instead of one. This works fine for simple exports without embedded commas, but check the output column count on anything more complex.", fr: "Non — il découpe chaque ligne sur les virgules sans tenir compte des guillemets, donc une valeur comme \"Doe, John\" entre guillemets sera scindée en deux colonnes au lieu d'une. Ça fonctionne bien pour des exports simples sans virgule intégrée, mais vérifiez le nombre de colonnes du résultat sur quelque chose de plus complexe." } },
    { q: { en: "What happens to nested objects or arrays when converting JSON to CSV?", fr: "Que deviennent les objets ou tableaux imbriqués en convertissant du JSON vers CSV ?" }, a: { en: "The converter expects a flat array of simple key-value objects. Nested objects or arrays inside a field will be stringified rather than expanded into their own columns — flatten your data first if you need each nested value in its own CSV column.", fr: "Le convertisseur attend un tableau plat d'objets clé-valeur simples. Les objets ou tableaux imbriqués dans un champ seront convertis en texte brut plutôt qu'éclatés en colonnes propres — aplatissez vos données d'abord si vous avez besoin de chaque valeur imbriquée dans sa propre colonne CSV." } },
  ],
  "deduplicate-lines": [
    { q: { en: "Does it remove lines with extra trailing spaces as duplicates?", fr: "Supprime-t-il les lignes avec des espaces de fin superflus comme des doublons ?" }, a: { en: "No — comparison is exact, character for character. \"apple\" and \"apple \" (with a trailing space) are treated as two distinct lines and both stay. Trim your data first if inconsistent spacing might be hiding duplicates.", fr: "Non — la comparaison est exacte, caractère par caractère. \"apple\" et \"apple \" (avec une espace en fin) sont traitées comme deux lignes distinctes et restent toutes les deux. Retirez les espaces de vos données d'abord si un espacement incohérent pourrait cacher des doublons." } },
    { q: { en: "Which occurrence of a duplicate does it keep — the first or the last?", fr: "Quelle occurrence d'un doublon est conservée — la première ou la dernière ?" }, a: { en: "The first one. If \"apple\" appears on line 2 and again on line 9, the line 9 copy is removed and the line 2 position is preserved in the output order.", fr: "La première. Si \"apple\" apparaît à la ligne 2 puis de nouveau à la ligne 9, la copie de la ligne 9 est supprimée et la position de la ligne 2 est préservée dans l'ordre du résultat." } },
  ],
  "diff-viewer": [
    { q: { en: "Does it highlight the specific word that changed within a line, like an IDE would?", fr: "Surligne-t-il le mot précis qui a changé dans une ligne, comme le ferait un IDE ?" }, a: { en: "No — the diff works line by line. If one word changes inside an otherwise identical line, the whole line shows as removed and re-added rather than just the changed word being highlighted.", fr: "Non — le diff fonctionne ligne par ligne. Si un mot change dans une ligne par ailleurs identique, toute la ligne s'affiche comme supprimée et rajoutée, plutôt que de surligner uniquement le mot modifié." } },
    { q: { en: "What algorithm does the diff use?", fr: "Quel algorithme utilise le diff ?" }, a: { en: "A longest-common-subsequence comparison — the same underlying approach used by git diff and the Unix diff command — which finds the minimal set of line insertions and deletions needed to turn the first text into the second.", fr: "Une comparaison par plus longue sous-séquence commune — la même approche que celle utilisée par git diff et la commande Unix diff — qui trouve l'ensemble minimal d'insertions et suppressions de lignes nécessaires pour transformer le premier texte en second." } },
    { q: { en: "Why does the whole paragraph show as changed when I only edited one word?", fr: "Pourquoi tout le paragraphe s'affiche-t-il comme modifié alors que je n'ai changé qu'un mot ?" }, a: { en: "The comparison works line by line, and a paragraph typed as a single unbroken line counts as one line. Break your text into shorter lines — one sentence per line, for example — before pasting, so the diff can isolate just the sentence that actually changed.", fr: "La comparaison fonctionne ligne par ligne, et un paragraphe tapé sur une seule ligne ininterrompue compte comme une seule ligne. Découpez votre texte en lignes plus courtes — une phrase par ligne, par exemple — avant de le coller, pour que le diff puisse isoler juste la phrase réellement modifiée." } },
    { q: { en: "Is this suitable for comparing full legal documents?", fr: "Est-ce adapté pour comparer des documents juridiques complets ?" }, a: { en: "For spotting which paragraphs changed, yes. For a word-level redline showing exactly which clause or term was altered inside a paragraph, split the text into one sentence per line first — otherwise a single changed word marks the entire paragraph as rewritten.", fr: "Pour repérer quels paragraphes ont changé, oui. Pour une redline au niveau du mot montrant précisément quelle clause ou quel terme a été modifié dans un paragraphe, découpez d'abord le texte en une phrase par ligne — sinon un seul mot changé marque tout le paragraphe comme réécrit." } },
  ],
  "env-formatter": [
    { q: { en: "Are my section comments preserved when I format the file?", fr: "Mes commentaires de section sont-ils conservés quand je formate le fichier ?" }, a: { en: "No — the formatter only processes KEY=value entries. Comments and blank lines used to organize the file into sections are dropped from the output entirely, so treat this as a tool for cleaning the entries themselves, not for reformatting a commented file in place.", fr: "Non — le formateur ne traite que les entrées KEY=valeur. Les commentaires et lignes vides utilisés pour organiser le fichier en sections sont entièrement retirés du résultat — considérez cet outil comme un nettoyeur d'entrées, pas comme un reformateur de fichier commenté en place." } },
    { q: { en: "If a key appears twice with different values, which one does it keep?", fr: "Si une clé apparaît deux fois avec des valeurs différentes, laquelle est conservée ?" }, a: { en: "The first one it encounters, reading top to bottom — matching how most .env loaders (like dotenv) resolve duplicate keys, where the first definition wins unless the loader is explicitly configured to override.", fr: "La première rencontrée, en lisant de haut en bas — ce qui correspond à la façon dont la plupart des chargeurs .env (comme dotenv) résolvent les clés en double, où la première définition l'emporte sauf configuration explicite du chargeur pour la surcharger." } },
  ],
  "image-compressor": [
    { q: { en: "Why did my file get bigger after choosing PNG?", fr: "Pourquoi mon fichier est-il devenu plus lourd après avoir choisi le PNG ?" }, a: { en: "PNG is lossless, so it can't shrink photographic detail the way JPEG or WebP compression does. Re-encoding a compressed photo into PNG often produces a larger file — the tool shows this honestly as a '+X% larger' result rather than hiding it.", fr: "Le PNG est sans perte, il ne peut donc pas réduire le détail photographique comme le fait la compression JPEG ou WebP. Réencoder une photo déjà compressée en PNG produit souvent un fichier plus lourd — l'outil l'affiche honnêtement en « +X% plus lourd » plutôt que de le masquer." } },
    { q: { en: "What quality setting should I use for web images?", fr: "Quel réglage de qualité utiliser pour des images web ?" }, a: { en: "75–85 for WebP is a reliable starting point for photos — visually close to the original with a meaningful size reduction. Go higher (90+) for images that will be zoomed or printed, lower (50–65) for thumbnails where sharpness matters less than load speed.", fr: "75 à 85 pour le WebP est un bon point de départ pour des photos — visuellement proche de l'original avec une réduction de poids significative. Montez plus haut (90+) pour des images zoomées ou imprimées, plus bas (50-65) pour des miniatures où la netteté compte moins que la vitesse de chargement." } },
  ],
  "lorem-ipsum": [
    { q: { en: "Does clicking generate again produce different text each time?", fr: "Cliquer pour régénérer produit-il un texte différent à chaque fois ?" }, a: { en: "No — for a given word, sentence or paragraph count, the output is always identical. The word sequence is deterministic rather than randomized, which makes mockups reproducible but means you won't get fresh variation by regenerating with the same settings.", fr: "Non — pour un nombre donné de mots, phrases ou paragraphes, le résultat est toujours identique. La séquence de mots est déterministe plutôt qu'aléatoire, ce qui rend les maquettes reproductibles mais signifie que vous n'obtiendrez pas de variation en régénérant avec les mêmes réglages." } },
    { q: { en: "Where does the Lorem Ipsum text actually come from?", fr: "D'où vient réellement le texte Lorem Ipsum ?" }, a: { en: "It's a scrambled excerpt from Cicero's 45 BC text De Finibus Bonorum et Malorum, which lost its original meaning through the scrambling and has been used as placeholder text in printing and publishing since at least the 1960s.", fr: "C'est un extrait brouillé du texte De Finibus Bonorum et Malorum de Cicéron (45 av. J.-C.), qui a perdu son sens original à travers ce brouillage et sert de texte de substitution dans l'imprimerie et l'édition depuis au moins les années 1960." } },
  ],
  "schema-generator": [
    { q: { en: "If the JSON-LD is valid, will it definitely show as a rich result in Google?", fr: "Si le JSON-LD est valide, apparaîtra-t-il forcément comme résultat enrichi dans Google ?" }, a: { en: "Not necessarily. Valid syntax and rich-result eligibility are different bars — Google often requires additional fields per type (like aggregateRating for Product) beyond what basic valid JSON-LD needs. Test the output in Google's Rich Results Test to see what's actually missing for eligibility.", fr: "Pas forcément. Syntaxe valide et éligibilité aux résultats enrichis sont deux barres différentes — Google exige souvent des champs supplémentaires par type (comme aggregateRating pour Product) au-delà de ce qu'un JSON-LD simplement valide nécessite. Testez le résultat dans le Rich Results Test de Google pour voir ce qui manque réellement pour l'éligibilité." } },
    { q: { en: "Which schema type should I use for a blog post?", fr: "Quel type de schema utiliser pour un article de blog ?" }, a: { en: "Article — it covers headline, description, author, publish date and URL, which matches what Google expects for standard article rich results. Use Product only for an actual purchasable item, and FAQPage only when the content genuinely is a list of questions and answers, not general body text.", fr: "Article — il couvre le titre, la description, l'auteur, la date de publication et l'URL, ce qui correspond à ce que Google attend pour les résultats enrichis d'article standard. N'utilisez Product que pour un article réellement achetable, et FAQPage uniquement quand le contenu est vraiment une liste de questions-réponses, pas du texte de corps général." } },
  ],
  "sitemap-generator": [
    { q: { en: "Does setting a high priority value actually help a page rank better?", fr: "Régler une priorité élevée aide-t-il vraiment une page à mieux se classer ?" }, a: { en: "No — Google has said for years it treats the priority field as, at best, a weak hint and largely ignores it for ranking or crawl prioritization. Don't spend time fine-tuning it; focus on an accurate lastmod date instead, which Google does use to judge whether a page needs recrawling.", fr: "Non — Google déclare depuis des années traiter le champ priority au mieux comme un indice faible et l'ignorer largement pour le classement ou la priorisation du crawl. Ne perdez pas de temps à l'affiner ; concentrez-vous plutôt sur une date lastmod exacte, que Google utilise réellement pour juger si une page mérite d'être recrawlée." } },
    { q: { en: "Can I set a different priority or changefreq for each URL?", fr: "Puis-je définir une priorité ou un changefreq différents pour chaque URL ?" }, a: { en: "Not in a single generation — this tool applies one shared value across the whole batch. For different values per URL group (e.g. homepage vs. archived pages), generate each group separately here and merge the resulting XML files by hand.", fr: "Pas en une seule génération — cet outil applique une valeur partagée à tout le lot. Pour des valeurs différentes par groupe d'URLs (page d'accueil vs pages archivées), générez chaque groupe séparément ici et fusionnez les fichiers XML résultants à la main." } },
  ],
  "slug-generator": [
    { q: { en: "Does it work with non-Latin scripts like Arabic, Russian or Chinese?", fr: "Fonctionne-t-il avec des écritures non latines comme l'arabe, le russe ou le chinois ?" }, a: { en: "Not well — the tool strips any character outside the basic Latin alphabet and digits, rather than transliterating it. A title entirely in Cyrillic or CJK characters can come out as an empty or near-empty slug. For those scripts, a dedicated transliteration library is a better fit than this tool.", fr: "Pas bien — l'outil supprime tout caractère hors de l'alphabet latin de base et des chiffres, plutôt que de le translittérer. Un titre entièrement en cyrillique ou en caractères CJK peut donner un slug vide ou presque vide. Pour ces écritures, une bibliothèque de translittération dédiée convient mieux que cet outil." } },
    { q: { en: "What happens to accented letters like é or ñ?", fr: "Que deviennent les lettres accentuées comme é ou ñ ?" }, a: { en: "They're normalized to their plain-ASCII base letter — é becomes e, ñ becomes n — using Unicode normalization to separate the letter from its accent mark, then discarding the accent. This works reliably for French, Spanish, German and Portuguese text.", fr: "Elles sont normalisées vers leur lettre ASCII de base — é devient e, ñ devient n — via une normalisation Unicode qui sépare la lettre de son accent, puis en écartant l'accent. Ça fonctionne de façon fiable pour du texte français, espagnol, allemand et portugais." } },
  ],
  "string-escape": [
    { q: { en: "Can I use the SQL escape mode instead of parameterized queries in my application?", fr: "Puis-je utiliser le mode d'échappement SQL à la place de requêtes paramétrées dans mon application ?" }, a: { en: "No — this is for safely writing a one-off query by hand, not a substitute for prepared statements in application code. Manual escaping is a fragile defense against SQL injection; always use parameterized queries or an ORM for real application code.", fr: "Non — c'est fait pour écrire une requête ponctuelle en toute sécurité à la main, pas un substitut aux instructions préparées dans du code applicatif. L'échappement manuel est une défense fragile contre l'injection SQL ; utilisez toujours des requêtes paramétrées ou un ORM pour du vrai code applicatif." } },
    { q: { en: "Why does Bash mode escape the dollar sign?", fr: "Pourquoi le mode Bash échappe-t-il le symbole dollar ?" }, a: { en: "Inside double-quoted Bash strings, $ triggers variable expansion (like $HOME) and backticks trigger command substitution. Escaping them with a backslash keeps the literal character instead of letting the shell interpret it as code.", fr: "Dans les chaînes Bash entre guillemets doubles, le $ déclenche l'expansion de variable (comme $HOME) et les backticks déclenchent la substitution de commande. Les échapper avec un antislash conserve le caractère littéral au lieu de laisser le shell l'interpréter comme du code." } },
  ],
  "svg-optimizer": [
    { q: { en: "Can optimization change how the SVG actually looks?", fr: "L'optimisation peut-elle changer l'apparence réelle du SVG ?" }, a: { en: "In edge cases, yes. SVGO's default preset is intentionally aggressive — it can merge paths or adjust attributes it considers redundant, which occasionally shifts rendering on icons with very precise strokes. Always visually check the optimized SVG before shipping it, don't assume it's pixel-identical.", fr: "Dans des cas limites, oui. Le preset par défaut de SVGO est volontairement agressif — il peut fusionner des chemins ou ajuster des attributs qu'il juge redondants, ce qui modifie parfois le rendu sur des icônes aux traits très précis. Vérifiez toujours visuellement le SVG optimisé avant de le déployer, ne présumez pas qu'il est identique au pixel près." } },
    { q: { en: "Where does the size reduction actually come from?", fr: "D'où vient réellement la réduction de poids ?" }, a: { en: "Mostly from removing markup that design tools add but browsers don't need — XML comments, editor namespace data, redundant metadata, and default attribute values that don't need to be stated explicitly. It's cleanup, not image degradation.", fr: "Surtout de la suppression de balisage que les outils de design ajoutent mais dont les navigateurs n'ont pas besoin — commentaires XML, données de namespace d'éditeur, métadonnées redondantes, et valeurs d'attributs par défaut qui n'ont pas besoin d'être déclarées explicitement. C'est du nettoyage, pas une dégradation de l'image." } },
  ],
  "zip-extractor": [
    { q: { en: "Can it open password-protected zip files?", fr: "Peut-il ouvrir des fichiers zip protégés par mot de passe ?" }, a: { en: "No — the underlying decompression library doesn't support encrypted zip entries (AES or classic ZipCrypto), so a password-protected archive will fail to read rather than prompt you for a password. Use a desktop archive manager for encrypted zips.", fr: "Non — la bibliothèque de décompression sous-jacente ne gère pas les entrées zip chiffrées (AES ou ZipCrypto classique), donc une archive protégée par mot de passe échouera à la lecture plutôt que de demander un mot de passe. Utilisez un gestionnaire d'archives de bureau pour des zip chiffrés." } },
    { q: { en: "Is there a file size limit?", fr: "Y a-t-il une limite de taille de fichier ?" }, a: { en: "No hard limit is enforced, but the whole archive is loaded into memory at once rather than streamed, so a multi-gigabyte file can hit your browser's memory ceiling on lower-end devices even if it would open fine in a desktop tool.", fr: "Aucune limite n'est imposée en dur, mais toute l'archive est chargée en mémoire d'un coup plutôt qu'en streaming, donc un fichier de plusieurs gigaoctets peut atteindre le plafond mémoire du navigateur sur des appareils moins puissants, même s'il s'ouvrirait sans problème dans un outil de bureau." } },
  ],
  "md-table": [
    { q: { en: "Do the pipes have to line up?", fr: "Les barres verticales doivent-elles être alignées ?" }, a: { en: "No. Only the separator row matters structurally: the number of segments in it sets the number of columns, and the colons inside it set the alignment. Ragged pipes render exactly like aligned ones. This tool aligns them anyway, because aligned source is far easier to read in a diff.", fr: "Non. Seule la ligne de séparation compte structurellement : le nombre de segments qu'elle contient fixe le nombre de colonnes, et les deux-points qu'on y place définissent l'alignement. Des barres irrégulières s'affichent exactement comme des barres alignées. Cet outil les aligne malgré tout, parce qu'un source aligné se lit bien plus facilement dans un diff." } },
    { q: { en: "How do I put a line break inside a cell?", fr: "Comment insérer un saut de ligne dans une cellule ?" }, a: { en: "Not with a real newline — that ends the row and breaks the table. The usual workaround is an inline HTML break tag, which most renderers accept inside a cell. Lists and fenced code blocks are unavailable for the same reason; inline code spans work normally.", fr: "Pas avec un vrai retour à la ligne — il termine la ligne du tableau et le casse. Le contournement habituel est une balise de saut HTML en ligne, que la plupart des moteurs de rendu acceptent dans une cellule. Listes et blocs de code délimités sont indisponibles pour la même raison ; le code en ligne, lui, fonctionne normalement." } },
    { q: { en: "Why does my table show as raw text on some sites?", fr: "Pourquoi mon tableau s'affiche-t-il en texte brut sur certains sites ?" }, a: { en: "Because tables are not part of Markdown itself. They come from GitHub Flavored Markdown, so they work on GitHub, GitLab, Obsidian, Notion and most static site generators, but a renderer running plain CommonMark shows the pipes as written. Most libraries expose the extension as an option to enable.", fr: "Parce que les tableaux ne font pas partie de Markdown lui-même. Ils viennent du GitHub Flavored Markdown : ils fonctionnent donc sur GitHub, GitLab, Obsidian, Notion et la plupart des générateurs de sites statiques, mais un moteur appliquant du CommonMark simple affiche les barres telles quelles. La plupart des bibliothèques proposent l'extension en option à activer." } },
    { q: { en: "What happens to a pipe character inside my data?", fr: "Que devient une barre verticale présente dans mes données ?" }, a: { en: "It must be escaped with a backslash, otherwise it is read as a column separator and shifts every following cell by one. A single unescaped pipe is the most common cause of a table rendering with the wrong number of columns.", fr: "Elle doit être échappée par un antislash, faute de quoi elle est lue comme un séparateur de colonne et décale d'un cran toutes les cellules suivantes. Une seule barre non échappée est la cause la plus fréquente d'un tableau affiché avec le mauvais nombre de colonnes." } },
  ],
  "jwt-generator": [
    { q: { en: "Are tokens generated here safe to use in production?", fr: "Les tokens générés ici sont-ils utilisables en production ?" }, a: { en: "The tokens themselves are correctly signed, but the practice is wrong: a production secret should never be typed into a web page, however local the signing is. Use this to produce test tokens against a development secret, and let your backend mint the real ones.", fr: "Les tokens eux-mêmes sont correctement signés, mais la pratique est mauvaise : un secret de production ne devrait jamais être saisi dans une page web, aussi locale que soit la signature. Servez-vous en pour produire des tokens de test avec un secret de développement, et laissez votre backend émettre les vrais." } },
    { q: { en: "Does my secret key leave the browser?", fr: "Ma clé secrète quitte-t-elle le navigateur ?" }, a: { en: "No. Signing uses the Web Crypto API in the page itself, so the key is never sent anywhere and no request is made. That said, it is still typed into a form field, so treat it as you would any secret entered on a shared or untrusted machine.", fr: "Non. La signature s'effectue via la Web Crypto API dans la page elle-même : la clé n'est envoyée nulle part et aucune requête n'est émise. Cela dit, elle est tout de même saisie dans un champ de formulaire — traitez-la comme n'importe quel secret tapé sur une machine partagée ou non maîtrisée." } },
    { q: { en: "Why is my token rejected as already expired, or never expires at all?", fr: "Pourquoi mon token est-il rejeté comme expiré, ou n'expire-t-il jamais ?" }, a: { en: "Both come from mixing seconds and milliseconds. exp is a Unix timestamp in seconds. If your own check compares it with Date.now(), which returns milliseconds, every token looks expired. If you write exp from Date.now() without dividing by 1000, the token is valid until the year 58,000 or so: it never expires, which is a security problem, not a rejection. Use Math.floor(Date.now() / 1000).", fr: "Les deux viennent d'une confusion entre secondes et millisecondes. exp est un timestamp Unix en secondes. Si votre propre contrôle le compare à Date.now(), qui renvoie des millisecondes, chaque token paraît expiré. Si vous écrivez exp à partir de Date.now() sans diviser par 1000, le token est valable jusque vers l'an 58 000 : il n'expire jamais, ce qui est une faille, pas un refus. Utilisez Math.floor(Date.now() / 1000)." } },
    { q: { en: "Why only HS256 and not RS256?", fr: "Pourquoi seulement HS256 et pas RS256 ?" }, a: { en: "HS256 is symmetric: one secret both signs and verifies, which suits a single service issuing and checking its own tokens. RS256 and ES256 sign with a private key and verify with a public one, so other services can validate without being able to forge. That asymmetric case needs key-pair management, which is outside what this tool does.", fr: "HS256 est symétrique : un même secret signe et vérifie, ce qui convient à un service unique qui émet et contrôle ses propres tokens. RS256 et ES256 signent avec une clé privée et vérifient avec une clé publique, permettant à d'autres services de valider sans pouvoir forger. Ce cas asymétrique suppose une gestion de paires de clés, hors du périmètre de cet outil." } },
  ],
  "utm-builder": [
    { q: { en: "Should I tag links between pages of my own site?", fr: "Faut-il baliser les liens entre les pages de mon propre site ?" }, a: { en: "No. UTM parameters on internal links restart the session attribution in your analytics, overwriting the real acquisition source with your own page — the original channel then disappears from the report. Tag only links you place somewhere you do not control: an email, an ad, a partner site.", fr: "Non. Des paramètres UTM sur des liens internes réamorcent l'attribution de session dans votre outil d'analyse : la source d'acquisition réelle est écrasée par votre propre page, et le canal d'origine disparaît du rapport. Ne balisez que les liens que vous placez là où vous n'avez pas la main : un e-mail, une annonce, un site partenaire." } },
    { q: { en: "Does capitalisation matter in UTM values?", fr: "La casse compte-t-elle dans les valeurs UTM ?" }, a: { en: "Yes, and it is a frequent silent failure. Most analytics platforms treat Newsletter and newsletter as two separate rows, and a trailing space pasted from a spreadsheet does the same. Nothing errors — the data just fragments, often noticed weeks later. Stay lowercase throughout, with hyphens instead of spaces.", fr: "Oui, et c'est un échec silencieux fréquent. La plupart des plateformes d'analyse traitent Newsletter et newsletter comme deux lignes distinctes, et une espace finale collée depuis un tableur produit le même effet. Rien ne signale d'erreur — les données se fragmentent simplement, et on s'en aperçoit souvent des semaines plus tard. Restez en minuscules, avec des traits d'union plutôt que des espaces." } },
    { q: { en: "Which of the five parameters are actually required?", fr: "Lesquels des cinq paramètres sont réellement nécessaires ?" }, a: { en: "Source, medium and campaign. Those are what analytics tools group by, and leaving one out drops the visit into an unhelpful bucket. Term and content are optional refinements, originally meant for paid keywords and for telling two creative variants apart.", fr: "La source, le medium et la campagne. Ce sont eux sur lesquels les outils d'analyse regroupent, et en omettre un fait tomber la visite dans une catégorie inexploitable. Le terme et le contenu sont des raffinements facultatifs, prévus à l'origine pour les mots-clés payants et pour distinguer deux variantes créatives." } },
  ],
  "readability": [
    { q: { en: "Does a high score mean the text is well written?", fr: "Un score élevé signifie-t-il que le texte est bien écrit ?" }, a: { en: "No. The formula only looks at sentence length and syllables per word — it has no notion of vocabulary, structure or meaning. A passage of short nonsense words scores as highly readable. Use it to compare two drafts of the same text, not as a verdict on quality.", fr: "Non. La formule ne regarde que la longueur des phrases et le nombre de syllabes par mot — elle n'a aucune notion de vocabulaire, de structure ni de sens. Un passage fait de mots courts et absurdes obtient un excellent score. Servez-vous en pour comparer deux versions d'un même texte, pas comme d'un verdict sur la qualité." } },
    { q: { en: "Can I use an English readability score on French text?", fr: "Puis-je appliquer un score de lisibilité anglais à du texte français ?" }, a: { en: "Not meaningfully — syllable-counting rules differ between the two languages, and English heuristics applied to French inflate the count and report the text as far harder than it is. This tool applies rules matched to the language rather than a single set for both.", fr: "Pas de façon exploitable — les règles de comptage des syllabes diffèrent entre les deux langues, et des heuristiques anglaises appliquées au français gonflent le compte et rapportent un texte bien plus difficile qu'il ne l'est. Cet outil applique des règles adaptées à la langue plutôt qu'un jeu unique pour les deux." } },
    { q: { en: "How accurate is the syllable count?", fr: "Quelle est la précision du comptage de syllabes ?" }, a: { en: "Approximate by design. No formula counts syllables exactly; the usual method groups consecutive vowels and applies corrections such as the silent final e in English. It handles common words well and misses on proper nouns, loanwords and irregular spellings — which is fine, since the score is a rough signal rather than a measurement.", fr: "Approximative par construction. Aucune formule ne compte les syllabes exactement ; la méthode habituelle regroupe les voyelles consécutives et applique des corrections comme le e muet final en anglais. Elle traite bien les mots courants et échoue sur les noms propres, les emprunts et les orthographes irrégulières — ce qui convient, le score étant un signal grossier plutôt qu'une mesure." } },
  ],
  "headers-checker": [
    { q: { en: "Why doesn't Referrer-Policy or Permissions-Policy change my grade?", fr: "Pourquoi Referrer-Policy et Permissions-Policy ne changent-ils pas ma note ?" }, a: { en: "Because they limit data leaks and browser features rather than block an attack outright. The grade only counts the four headers that stop XSS, clickjacking, MIME sniffing and HTTPS downgrades. The other two are still listed with a recommendation, and they're worth adding: a Referrer-Policy line takes a minute.", fr: "Parce qu'ils limitent des fuites de données et des fonctionnalités du navigateur au lieu de bloquer une attaque directement. La note ne compte que les quatre en-têtes qui stoppent le XSS, le clickjacking, le MIME sniffing et le retour forcé en HTTP. Les deux autres restent affichés avec une recommandation, et valent la peine : une ligne Referrer-Policy s'ajoute en une minute." } },
    { q: { en: "I added the header but the checker still says it's missing. Why?", fr: "J'ai ajouté l'en-tête mais l'outil le dit toujours absent. Pourquoi ?" }, a: { en: "Three usual causes. The server wasn't reloaded after the change. A CDN is serving a cached copy of the old response, so purge it. Or, on Nginx, the page you tested matches a location block with its own add_header, which cancels every header inherited from the server block. Results here are also kept for one minute, so give it a moment before retesting.", fr: "Trois causes habituelles. Le serveur n'a pas été rechargé après la modification. Un CDN sert une copie en cache de l'ancienne réponse : purgez-le. Ou, sous Nginx, la page testée tombe dans un bloc location qui a son propre add_header, ce qui annule tous les en-têtes hérités du bloc server. Les résultats sont aussi gardés une minute ici : patientez un instant avant de retester." } },
    { q: { en: "Should I still set X-XSS-Protection?", fr: "Faut-il encore définir X-XSS-Protection ?" }, a: { en: "No. It controlled the XSS filter built into older browsers, and that filter is gone: Chrome removed it in version 78 and Firefox never had one. OWASP now recommends leaving the header out or setting it to 0. A Content-Security-Policy is what actually protects against XSS today, which is why the checker ignores X-XSS-Protection.", fr: "Non. Il pilotait le filtre XSS intégré aux anciens navigateurs, et ce filtre a disparu : Chrome l'a retiré à la version 78 et Firefox n'en a jamais eu. L'OWASP recommande désormais de ne pas l'envoyer ou de le régler à 0. C'est une Content-Security-Policy qui protège réellement du XSS aujourd'hui, d'où le fait que l'outil ignore X-XSS-Protection." } },
    { q: { en: "X-Frame-Options or CSP frame-ancestors: which one should I use?", fr: "X-Frame-Options ou frame-ancestors dans la CSP : lequel utiliser ?" }, a: { en: "frame-ancestors is the modern replacement and it wins when both are present in browsers that support it. X-Frame-Options still covers older browsers, so sending both costs nothing. The checker accepts either one: a CSP with frame-ancestors marks X-Frame-Options as covered.", fr: "frame-ancestors est le remplaçant moderne et l'emporte quand les deux sont présents, dans les navigateurs qui le gèrent. X-Frame-Options couvre encore les anciens navigateurs, donc envoyer les deux ne coûte rien. L'outil accepte l'un ou l'autre : une CSP avec frame-ancestors marque X-Frame-Options comme couvert." } },
    { q: { en: "Can I check a site on localhost or my company network?", fr: "Puis-je tester un site en localhost ou sur le réseau de mon entreprise ?" }, a: { en: "No. The request is made from our server, which refuses localhost, private IP ranges and internal TLDs so it can't be used to probe private networks. For those sites, run curl -sIL against the address from a machine that can reach it.", fr: "Non. La requête part de notre serveur, qui refuse localhost, les plages d'IP privées et les TLD internes pour ne pas servir à sonder des réseaux privés. Pour ces sites, lancez curl -sIL sur l'adresse depuis une machine qui y a accès." } },
  ],
  "toml-json": [
    { q: { en: "Why do my TOML dates become strings in JSON?", fr: "Pourquoi mes dates TOML deviennent-elles des chaînes en JSON ?" }, a: { en: "Because JSON has no date type. The value is written in ISO 8601, so any language can parse it back into a date, but converting that JSON back to TOML gives a quoted string, not a TOML date.", fr: "Parce que le JSON n'a pas de type date. La valeur est écrite au format ISO 8601, donc n'importe quel langage peut la relire comme une date, mais reconvertir ce JSON en TOML donne une chaîne entre guillemets, pas une date TOML." } },
    { q: { en: "Where did the keys with null values go?", fr: "Où sont passées les clés qui valaient null ?" }, a: { en: "TOML can't represent null, so those keys are left out of the TOML output. The tool lists each one above the result. If the key must exist, give it a real value, such as an empty string or false, before converting.", fr: "Le TOML ne sait pas représenter null : ces clés sont omises du résultat TOML. L'outil les liste au-dessus du résultat. Si la clé doit exister, donnez-lui une vraie valeur, comme une chaîne vide ou false, avant de convertir." } },
    { q: { en: "Why does my tsconfig.json fail to convert?", fr: "Pourquoi mon tsconfig.json refuse-t-il la conversion ?" }, a: { en: "Most likely because of comments or trailing commas. TypeScript and VS Code accept them in their config files, but standard JSON doesn't. Remove them and the file will convert.", fr: "Très probablement à cause de commentaires ou de virgules finales. TypeScript et VS Code les acceptent dans leurs fichiers de config, mais le JSON standard non. Retirez-les et le fichier passera." } },
    { q: { en: "Are TOML comments kept?", fr: "Les commentaires TOML sont-ils conservés ?" }, a: { en: "No. JSON has no comments, and the TOML generated from JSON starts without any. If your TOML file is documented with comments, don't overwrite it with a converted version; use the conversion to read it.", fr: "Non. Le JSON n'a pas de commentaires, et le TOML généré depuis du JSON n'en contient aucun. Si votre fichier TOML est documenté par des commentaires, ne l'écrasez pas avec une version convertie ; servez-vous de la conversion pour le lire." } },
    { q: { en: "Why did 3.0 become 3?", fr: "Pourquoi 3.0 est-il devenu 3 ?" }, a: { en: "JSON has a single number type, so the difference between the integer 3 and the float 3.0 isn't kept. Converted back to TOML, the value is written as the integer 3. If a program expects a float for that key, write 3.0 by hand in the final TOML.", fr: "Le JSON n'a qu'un seul type de nombre : la différence entre l'entier 3 et le décimal 3.0 est perdue. Reconvertie en TOML, la valeur s'écrit comme l'entier 3. Si un programme attend un décimal pour cette clé, écrivez 3.0 à la main dans le TOML final." } },
  ],
};

/**
 * FAQ d'une page outil.
 *
 * Les questions transverses (gratuité, confidentialité, hors ligne) étaient
 * ajoutées en tête de chaque page, avec des réponses identiques au mot près sur
 * les 112 pages outils : jusqu'à 45 % du texte d'une page se retrouvait dupliqué
 * ailleurs sur le site. C'est précisément ce que Google sanctionne sous
 * l'étiquette « contenu à faible valeur informative ».
 *
 * Deux correctifs. D'abord les questions propres à l'outil passent devant : ce
 * sont elles qui justifient la page. Ensuite, dès qu'un outil en possède au
 * moins trois, on ne conserve du bloc transverse que la question de
 * confidentialité — la seule dont la réponse varie réellement selon l'outil
 * (traitement local ou via proxy) et que les utilisateurs viennent chercher.
 */
const PRIVACY_ITEM_INDEX = 1;

export function toolFaqItems(tool: Tool): FaqItem[] {
  const isNetwork = tool.privacy === "network";
  const specific = SPECIFIC[tool.slug] ?? [];
  const transverse = universal(tool.name, isNetwork);

  return specific.length >= 3
    ? [...specific, transverse[PRIVACY_ITEM_INDEX]!]
    : [...specific, ...transverse];
}

/**
 * La seule question transverse à reprendre sur une page de conversion.
 *
 * Ces pages portent déjà leur propre FAQ ; y recopier tout le bloc transverse,
 * ou pire les questions de l'outil mère, ne ferait que dupliquer du texte sur
 * les 28 pages de paires. La confidentialité est la seule que les visiteurs
 * viennent réellement y chercher.
 */
export function privacyFaqItem(tool: Tool): FaqItem {
  return universal(tool.name, tool.privacy === "network")[PRIVACY_ITEM_INDEX]!;
}
